export default JSON.parse("{\"workId\":\"li-ji\",\"chapter\":{\"id\":\"li-ji_ch-12\",\"workId\":\"li-ji\",\"order\":12,\"title\":\"內則\",\"difficulty\":4,\"estimatedMinutes\":16,\"passageIds\":[\"li-ji_ch-12_p-1\",\"li-ji_ch-12_p-2\",\"li-ji_ch-12_p-3\",\"li-ji_ch-12_p-4\",\"li-ji_ch-12_p-5\",\"li-ji_ch-12_p-6\",\"li-ji_ch-12_p-7\",\"li-ji_ch-12_p-8\",\"li-ji_ch-12_p-9\",\"li-ji_ch-12_p-10\",\"li-ji_ch-12_p-11\",\"li-ji_ch-12_p-12\",\"li-ji_ch-12_p-13\",\"li-ji_ch-12_p-14\",\"li-ji_ch-12_p-15\",\"li-ji_ch-12_p-16\",\"li-ji_ch-12_p-17\",\"li-ji_ch-12_p-18\",\"li-ji_ch-12_p-19\",\"li-ji_ch-12_p-20\",\"li-ji_ch-12_p-21\",\"li-ji_ch-12_p-22\",\"li-ji_ch-12_p-23\",\"li-ji_ch-12_p-24\",\"li-ji_ch-12_p-25\",\"li-ji_ch-12_p-26\",\"li-ji_ch-12_p-27\",\"li-ji_ch-12_p-28\",\"li-ji_ch-12_p-29\",\"li-ji_ch-12_p-30\",\"li-ji_ch-12_p-31\",\"li-ji_ch-12_p-32\",\"li-ji_ch-12_p-33\",\"li-ji_ch-12_p-34\",\"li-ji_ch-12_p-35\",\"li-ji_ch-12_p-36\",\"li-ji_ch-12_p-37\",\"li-ji_ch-12_p-38\",\"li-ji_ch-12_p-39\",\"li-ji_ch-12_p-40\",\"li-ji_ch-12_p-41\",\"li-ji_ch-12_p-42\",\"li-ji_ch-12_p-43\",\"li-ji_ch-12_p-44\",\"li-ji_ch-12_p-45\",\"li-ji_ch-12_p-46\",\"li-ji_ch-12_p-47\",\"li-ji_ch-12_p-48\",\"li-ji_ch-12_p-49\",\"li-ji_ch-12_p-50\",\"li-ji_ch-12_p-51\",\"li-ji_ch-12_p-52\",\"li-ji_ch-12_p-53\",\"li-ji_ch-12_p-54\",\"li-ji_ch-12_p-55\",\"li-ji_ch-12_p-56\",\"li-ji_ch-12_p-57\",\"li-ji_ch-12_p-58\",\"li-ji_ch-12_p-59\",\"li-ji_ch-12_p-60\",\"li-ji_ch-12_p-61\",\"li-ji_ch-12_p-62\",\"li-ji_ch-12_p-63\",\"li-ji_ch-12_p-64\",\"li-ji_ch-12_p-65\",\"li-ji_ch-12_p-66\",\"li-ji_ch-12_p-67\",\"li-ji_ch-12_p-68\",\"li-ji_ch-12_p-69\",\"li-ji_ch-12_p-70\",\"li-ji_ch-12_p-71\",\"li-ji_ch-12_p-72\",\"li-ji_ch-12_p-73\",\"li-ji_ch-12_p-74\",\"li-ji_ch-12_p-75\",\"li-ji_ch-12_p-76\",\"li-ji_ch-12_p-77\",\"li-ji_ch-12_p-78\",\"li-ji_ch-12_p-79\",\"li-ji_ch-12_p-80\",\"li-ji_ch-12_p-81\",\"li-ji_ch-12_p-82\",\"li-ji_ch-12_p-83\"],\"tags\":[\"儒家\",\"禮樂\"]},\"passages\":[{\"id\":\"li-ji_ch-12_p-1\",\"chapterId\":\"li-ji_ch-12\",\"order\":1,\"canonicalText\":\"后王命冢宰，降德於眾兆民。\",\"sentenceIds\":[\"li-ji_ch-12_p-1_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"后王命冢宰，降崇高德行與品性修養於眾兆民。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 1 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「后王命冢宰，降德於眾兆民」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「后王命冢宰，降德於眾兆民。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-2\",\"chapterId\":\"li-ji_ch-12\",\"order\":2,\"canonicalText\":\"子事父母，雞初鳴，鹹盥漱，櫛縰笄總，拂髦冠緌纓，端韠紳，搢笏。左右佩用，左佩紛帨、刀、礪、小觿、金燧，右佩玦、捍、管、遰、大觿、木燧，偪，屨著綦。\",\"sentenceIds\":[\"li-ji_ch-12_p-2_s-1\",\"li-ji_ch-12_p-2_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"為人子女侍奉父母之禮：雄雞初鳴破曉之時，子女皆起身洗臉漱口，梳理頭髮並以縰束髮、簪上髮笄以總繩束髮，拂拭額前美髮、戴好禮冠繫正冠帶與纓飾，穿戴端莊之玄端禮服、蔽膝與紳帶，將笏板插於帶間。左右腰間佩帶日常器用：左側佩帶拭巾手帕、小刀、磨刀石、小觿錐、金燧取火之器；右側佩帶射決玦板、臂捍、筆管、手帕袋、大觿錐、木燧鑽火之器，穿好行縢護腿與繫有鞋帶的鞋履，恭敬前往父母長輩居室晨昏省定。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 2 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子事父母，雞初鳴，鹹盥漱，櫛縰笄總，拂髦冠緌纓，端韠紳，搢笏」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子事父母，雞初鳴，鹹盥漱，櫛縰笄總，拂髦冠緌纓，端韠……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-3\",\"chapterId\":\"li-ji_ch-12\",\"order\":3,\"canonicalText\":\"婦事舅姑，如事父母。雞初鳴，鹹盥漱，櫛縰，笄總，衣紳。左佩紛帨、刀、礪、小觿、金燧，右佩箴、管、線、纊，施縏帙，大觿、木燧、衿纓，綦屨。\",\"sentenceIds\":[\"li-ji_ch-12_p-3_s-1\",\"li-ji_ch-12_p-3_s-2\",\"li-ji_ch-12_p-3_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"為人兒媳侍奉公婆，如同侍奉親生父母。雄雞初鳴拂曉之時，媳婦起牀洗臉漱口，梳髮束髻、簪笄繫總、穿戴整齊深衣大帶。左邊腰間佩帶手巾抹布、削刀、磨刀石、解結小觿錐、取火金燧；右側佩帶針囊、筆管、絲線、絲綿，佩戴盛放小物的縏囊香袋、大觿錐、木燧、佩巾纓帶，腳穿繫緊鞋帶之鞋履，恭肅前往公婆榻前侍奉請安。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 3 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「婦事舅姑，如事父母」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「婦事舅姑，如事父母。雞初鳴，鹹盥漱，櫛縰，笄總，衣紳……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-4\",\"chapterId\":\"li-ji_ch-12\",\"order\":4,\"canonicalText\":\"以適父母舅姑之所，及所，下氣怡聲，問衣燠寒，疾痛苛癢，而敬抑搔之。出入，則或先或後，而敬扶持之。進盥，少者奉盤，長者奉水，請沃盥，盥卒授巾。問所欲而敬進之，柔色以溫之，饘酏、酒醴、芼羹、菽麥、蕡稻、黍粱、秫唯所欲，棗、栗、飴、蜜以甘之，堇、荁、枌、榆免槁薧滫以滑之，脂膏以膏之，父母舅姑必嘗之而後退。\",\"sentenceIds\":[\"li-ji_ch-12_p-4_s-1\",\"li-ji_ch-12_p-4_s-2\",\"li-ji_ch-12_p-4_s-3\",\"li-ji_ch-12_p-4_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"以適父母舅姑的所，及所，下氣怡聲，問衣燠寒，疾痛苛癢，而且敬抑搔的。出入，則或先或後，而且敬扶持的。進盥，少的人或禮儀規程與道崇高德行與品性修養規範制規範奉盤，長的人或禮儀規程與道崇高德行與品性修養規範制規範奉水，請沃盥，盥卒授巾。問所欲而且敬進的，柔色以溫的，饘酏、酒醴、芼羹、菽麥、蕡稻、黍粱、秫唯所欲，棗、栗、飴、蜜以甘的，堇、荁、枌、榆免槁薧滫以滑的，脂膏以膏的，父母舅姑必嘗的而且後退。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 4 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「以適父母舅姑之所，及所，下氣怡聲，問衣燠寒，疾痛苛癢，而敬抑搔之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「以適父母舅姑之所，及所，下氣怡聲，問衣燠寒，疾痛苛癢……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-5\",\"chapterId\":\"li-ji_ch-12\",\"order\":5,\"canonicalText\":\"男女未冠笄者，雞初鳴，鹹盥漱，櫛縰，拂髦總角，衿纓，皆佩容臭，昧爽而朝，問何食飲矣。若已食則退，若未食則佐長者視具。\",\"sentenceIds\":[\"li-ji_ch-12_p-5_s-1\",\"li-ji_ch-12_p-5_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"男女未冠笄的人或禮儀規程與道崇高德行與品性修養規範制規範，雞初鳴，鹹盥漱，櫛縰，拂髦總角，衿纓，皆佩容臭，昧爽而且朝，問何食飲矣。若已食則退，若未食則佐長的人或禮儀規程與道崇高德行與品性修養規範制規範視具。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 5 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「男女未冠笄者，雞初鳴，鹹盥漱，櫛縰，拂髦總角，衿纓，皆佩容臭，昧爽而朝，問何食飲矣」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「男女未冠笄者，雞初鳴，鹹盥漱，櫛縰，拂髦總角，衿纓，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-6\",\"chapterId\":\"li-ji_ch-12\",\"order\":6,\"canonicalText\":\"凡內外，雞初鳴，鹹盥漱，衣服，斂枕簟，灑掃室堂及庭，布席，各從其事。\",\"sentenceIds\":[\"li-ji_ch-12_p-6_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡是家庭內部無論內室婦女或外堂男子，清晨雄雞初鳴報曉之際，大家都要立刻起身盥洗雙手、漱洗口腔，穿戴整齊衣冠衣裳，卷收整理好枕頭與竹席，提水灑水清掃堂屋居室與前後庭院，端正鋪設坐席，隨後依照各自的職責分工各司其職操持勞作。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 6 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡內外，雞初鳴，鹹盥漱，衣服，斂枕簟，灑掃室堂及庭，布席，各從其事」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡內外，雞初鳴，鹹盥漱，衣服，斂枕簟，灑掃室堂及庭，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-7\",\"chapterId\":\"li-ji_ch-12\",\"order\":7,\"canonicalText\":\"孺子蚤寢晏起，唯所欲，食無時。\",\"sentenceIds\":[\"li-ji_ch-12_p-7_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"對於年幼未成年的孩童幼子，起居應當寬厚隨順：允許其早睡遲起，順其自然性情，飲食亦無須強求固定時節，以順應其身心成長之自然生機。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 7 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孺子蚤寢晏起，唯所欲，食無時」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孺子蚤寢晏起，唯所欲，食無時。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-8\",\"chapterId\":\"li-ji_ch-12\",\"order\":8,\"canonicalText\":\"由命士以上，父子皆異宮。昧爽而朝，慈以旨甘，日出而退，各從其事，日入而夕，慈以旨甘。\",\"sentenceIds\":[\"li-ji_ch-12_p-8_s-1\",\"li-ji_ch-12_p-8_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"由命士人階層以上，父子皆異宮。昧爽而且朝，慈以旨甘，日出而且退，各從他的事，日入而且夕，慈以旨甘。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 8 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「由命士以上，父子皆異宮」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「由命士以上，父子皆異宮。昧爽而朝，慈以旨甘，日出而退……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-9\",\"chapterId\":\"li-ji_ch-12\",\"order\":9,\"canonicalText\":\"父母舅姑將坐，奉席請何鄉；將衽，長者奉席請何趾。少者執牀與坐，御者舉幾，斂席與簟，縣衾篋枕，斂簟而襡之。\",\"sentenceIds\":[\"li-ji_ch-12_p-9_s-1\",\"li-ji_ch-12_p-9_s-2\",\"li-ji_ch-12_p-9_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"父母舅姑將坐，奉席請何鄉；將衽，長的人或禮儀規程與道崇高德行與品性修養規範制規範奉席請何趾。少的人或禮儀規程與道崇高德行與品性修養規範制規範執牀與坐，御的人或禮儀規程與道崇高德行與品性修養規範制規範舉幾，斂席與簟，縣衾篋枕，斂簟而且襡的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 9 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「父母舅姑將坐，奉席請何鄉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「父母舅姑將坐，奉席請何鄉；將衽，長者奉席請何趾。少者……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-10\",\"chapterId\":\"li-ji_ch-12\",\"order\":10,\"canonicalText\":\"父母舅姑之衣衾簟席枕幾不傳，杖屨只敬之，勿敢近。敦牟卮匜，非餕莫敢用；與恆食飲，非餕，莫之敢飲食。\",\"sentenceIds\":[\"li-ji_ch-12_p-10_s-1\",\"li-ji_ch-12_p-10_s-2\",\"li-ji_ch-12_p-10_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"父母舅姑的衣衾簟席枕幾不傳，杖屨只敬的，勿敢近。敦牟卮匜，絕不是餕莫敢用；與恆食飲，絕不是餕，莫的敢飲食。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 10 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「父母舅姑之衣衾簟席枕幾不傳，杖屨只敬之，勿敢近」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「父母舅姑之衣衾簟席枕幾不傳，杖屨只敬之，勿敢近。敦牟……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-11\",\"chapterId\":\"li-ji_ch-12\",\"order\":11,\"canonicalText\":\"父母在，朝夕恆食，子婦佐餕，既食恆餕，父沒母存，冢子御食，羣子婦佐餕如初，旨甘柔滑，孺子餕。\",\"sentenceIds\":[\"li-ji_ch-12_p-11_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"父母在世之時，每日早晚進獻定時膳食，子婦在旁輔助長輩進餐並分食剩餘飯菜；長輩吃完後子婦方始進食。若父親去世而母親健在，則由長子（嫡長子）陪同母親進餐，其餘諸子與兒媳如常在旁輔助進食；各種甘甜鮮美柔滑的精緻美食，優先留予年幼孩童享用。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 11 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「父母在，朝夕恆食，子婦佐餕，既食恆餕，父沒母存，冢子御食，羣子婦佐餕如初，旨甘柔滑，孺子餕」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「父母在，朝夕恆食，子婦佐餕，既食恆餕，父沒母存，冢子……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-12\",\"chapterId\":\"li-ji_ch-12\",\"order\":12,\"canonicalText\":\"在父母舅姑之所，有命之，應唯敬對。進退周旋慎齊，升降出入揖遊，不敢噦噫、嚏咳、欠伸、跛倚、睇視，不敢唾洟；寒不敢襲，癢不敢搔；不有敬事，不敢袒裼，不涉不撅，褻衣衾不見裏。\",\"sentenceIds\":[\"li-ji_ch-12_p-12_s-1\",\"li-ji_ch-12_p-12_s-2\",\"li-ji_ch-12_p-12_s-3\",\"li-ji_ch-12_p-12_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在父母與公婆舅姑的起居居所侍奉之時，長輩若有使喚指令，晚輩應當迅捷恭順地應答「唯」以示敬意。進前退後、轉折周旋時姿態必須戒慎整齊，上下台階、出入門戶時必須從容作揖揖讓而不可疾走喧譁，切不可在尊長面前乾嘔噦吐、打嗝噫氣、打噴嚏、劇烈咳嗽、打哈欠伸懶腰、一腳跛立斜倚牆柱，不可斜眼睥睨窺視，不可在長輩面前隨地吐痰擤鼻涕；天寒之時不敢擅自加穿重衣覆蔽，身上發癢之時不敢伸手搔抓止癢；若非有盛大敬肅的典禮公務，不可擅自袒露手臂衣襟，若非涉水渡河不可隨意掀撩提捲衣擺，私下穿著的貼身褻衣與蓋身的被褥，嚴禁翻露其內層襯裡以示端肅。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 12 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「在父母舅姑之所，有命之，應唯敬對」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「在父母舅姑之所，有命之，應唯敬對。進退周旋慎齊，升降……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-13\",\"chapterId\":\"li-ji_ch-12\",\"order\":13,\"canonicalText\":\"父母唾洟不見，冠帶垢，和灰請漱；衣裳垢，和灰請浣；衣裳綻裂，紉箴請補綴。五日，則燂湯請浴，三日具沐，其間面垢，燂潘請靧；足垢，燂湯請洗。少事長，賤事貴，共帥時。\",\"sentenceIds\":[\"li-ji_ch-12_p-13_s-1\",\"li-ji_ch-12_p-13_s-2\",\"li-ji_ch-12_p-13_s-3\",\"li-ji_ch-12_p-13_s-4\",\"li-ji_ch-12_p-13_s-5\",\"li-ji_ch-12_p-13_s-6\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"父母若咳吐痰沫或涕淚，晚輩要及時擦拭清潔不可使其穢跡顯露在外。父母的冠帽帶飾若有污垢，要調和草木鹼灰恭請拿來洗滌浸漱；衣裳若沾染污漬，要調和草木灰水恭請拿來洗滌乾淨；衣裳若有破綻撕裂，要穿針引線恭敬請命予以縫補綴合。每隔五天，便要燒熱溫水恭請父母洗澡沐浴；每隔三天，便要備妥熱水香湯恭請父母洗髮梳頭。在這期間父母若是面部有塵垢，要溫熱淘米水（潘水）恭請父母洗面洗臉；若是腳底有污垢，要燒好熱水恭請父母洗腳濯足。晚輩侍奉長輩、身分卑者侍奉尊者，皆當共同遵循推行這套孝敬規範。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 13 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「父母唾洟不見，冠帶垢，和灰請漱」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「父母唾洟不見，冠帶垢，和灰請漱；衣裳垢，和灰請浣；衣……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-14\",\"chapterId\":\"li-ji_ch-12\",\"order\":14,\"canonicalText\":\"男不言內，女不言外。非祭非喪，不相授器。其相授，則女受以篚，其無篚則皆坐奠之而後取之。外內不共井，不共湢浴，不通寢席，不通乞假，男女不通衣裳，內言不出，外言不入。\",\"sentenceIds\":[\"li-ji_ch-12_p-14_s-1\",\"li-ji_ch-12_p-14_s-2\",\"li-ji_ch-12_p-14_s-3\",\"li-ji_ch-12_p-14_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"男不言內，女不言外。絕不是祭絕不是喪，不相授器。他的相授，則女受以篚，他的無篚則皆坐奠的而且後取的。外內不共井，不共湢浴，不通寢席，不通乞假，男女不通衣裳，內言不出，外言不入。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 14 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「男不言內，女不言外」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「男不言內，女不言外。非祭非喪，不相授器。其相授，則女……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-15\",\"chapterId\":\"li-ji_ch-12\",\"order\":15,\"canonicalText\":\"男子入內，不嘯不指，夜行以燭，無燭則止。女子出門，必擁蔽其面，夜行以燭，無燭則止。道路：男子由右，女子由左。\",\"sentenceIds\":[\"li-ji_ch-12_p-15_s-1\",\"li-ji_ch-12_p-15_s-2\",\"li-ji_ch-12_p-15_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"男子步入內宅深閣之際，不可隨口吹口哨呼嘯，不可隨意伸手指手畫腳，夜間在宅內行走必須手執燈燭照明，若是沒有燈燭照明就應當停步止行以避嫌隙。女子走出內門閨閣之際，必須用面紗帷帽遮蔽遮掩其容貌，夜間行走也必須手執燈燭，若是沒有燈燭照明就應當止步不前。在庭院道路上行走時：男子依照禮數由右側通道前行，女子則依照禮數由左側通道前行。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 15 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「男子入內，不嘯不指，夜行以燭，無燭則止」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「男子入內，不嘯不指，夜行以燭，無燭則止。女子出門，必……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-16\",\"chapterId\":\"li-ji_ch-12\",\"order\":16,\"canonicalText\":\"子婦孝者、敬者，父母舅姑之命，勿逆勿怠。若飲食之，雖不耆，必嘗而待；加之衣服，雖不欲，必服而待；加之事，人待之，己雖弗欲，姑與之，而姑使之，而後復之。\",\"sentenceIds\":[\"li-ji_ch-12_p-16_s-1\",\"li-ji_ch-12_p-16_s-2\",\"li-ji_ch-12_p-16_s-3\",\"li-ji_ch-12_p-16_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子婦孝的人或禮儀規程與道崇高德行與品性修養規範制規範、敬的人或禮儀規程與道崇高德行與品性修養規範制規範，父母舅姑的命，勿逆勿怠。若飲食的，雖不耆，必嘗而且待；加的衣服，雖不欲，必服而且待；加的事，人待的，己雖弗欲，姑與的，而且姑使的，而且後復的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 16 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子婦孝者、敬者，父母舅姑之命，勿逆勿怠」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子婦孝者、敬者，父母舅姑之命，勿逆勿怠。若飲食之，雖……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-17\",\"chapterId\":\"li-ji_ch-12\",\"order\":17,\"canonicalText\":\"子婦有勤勞之事，雖甚愛之，姑縱之，而寧數休之。子婦未孝未敬，勿庸疾怨，姑教之；若不可教，而後怒之；不可怒，子放婦出，而不表禮焉。\",\"sentenceIds\":[\"li-ji_ch-12_p-17_s-1\",\"li-ji_ch-12_p-17_s-2\",\"li-ji_ch-12_p-17_s-3\",\"li-ji_ch-12_p-17_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子婦有勤勞的事，雖甚愛的，姑縱的，而且寧數休的。子婦未孝未敬，勿庸疾怨，姑教的；若不可教，而且後怒的；不可怒，子放婦出，而且不表禮儀規程與道崇高德行與品性修養規範焉。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 17 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子婦有勤勞之事，雖甚愛之，姑縱之，而寧數休之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子婦有勤勞之事，雖甚愛之，姑縱之，而寧數休之。子婦未……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-18\",\"chapterId\":\"li-ji_ch-12\",\"order\":18,\"canonicalText\":\"父母有過，下氣怡色，柔聲以諫。諫若不入，起敬起孝，說則復諫；不說，與其得罪於鄉黨州閭，寧孰諫。父母怒、不說，而撻之流血，不敢疾怨，起敬起孝。\",\"sentenceIds\":[\"li-ji_ch-12_p-18_s-1\",\"li-ji_ch-12_p-18_s-2\",\"li-ji_ch-12_p-18_s-3\",\"li-ji_ch-12_p-18_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"父母若是有了過錯與過失，子女應當平心靜氣、抑制浮躁，現出溫和愉悅的臉色，用最輕柔順遜的聲音委婉勸諫。如果勸諫之言父母不肯聽從採納，子女應當發自內心生出更多的恭敬與純孝，等待父母心情高興之時再度上前懇切進諫；若是父母依然不高興，但想到與其讓父母作惡而獲罪得罪於鄉里鄰里鄉黨，寧可一次又一次反覆進諫到底。即便父母因此勃然大怒、心中不悅，甚至拿起竹板藤條抽打自己至皮開肉綻鮮血直流，子女心中亦絕不敢產生絲毫怨恨嫉恨之意，反而要更加油然而生崇敬與純孝之心。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 18 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「父母有過，下氣怡色，柔聲以諫」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「父母有過，下氣怡色，柔聲以諫。諫若不入，起敬起孝，說……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-19\",\"chapterId\":\"li-ji_ch-12\",\"order\":19,\"canonicalText\":\"父母有婢子若庶子、庶孫，甚愛之，雖父母沒，沒身敬之不衰。\",\"sentenceIds\":[\"li-ji_ch-12_p-19_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"父母有婢子若庶子、庶孫，甚愛的，雖父母沒，沒身敬的不衰。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 19 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「父母有婢子若庶子、庶孫，甚愛之，雖父母沒，沒身敬之不衰」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「父母有婢子若庶子、庶孫，甚愛之，雖父母沒，沒身敬之不衰。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-20\",\"chapterId\":\"li-ji_ch-12\",\"order\":20,\"canonicalText\":\"子有二妾，父母愛一人焉，子愛一人焉，由衣服飲食，由執事，毋敢視父母所愛，雖父母沒不衰。子甚宜其妻，父母不說，出；子不宜其妻，父母曰：「是善事我。」子行夫婦之禮焉，沒身不衰。\",\"sentenceIds\":[\"li-ji_ch-12_p-20_s-1\",\"li-ji_ch-12_p-20_s-2\",\"li-ji_ch-12_p-20_s-3\",\"li-ji_ch-12_p-20_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子有二妾，父母愛一人焉，子愛一人焉，由衣服飲食，由執事，毋敢視父母所愛，雖父母沒不衰。子甚宜他的妻，父母不說，出；子不宜他的妻，父母說道：「是善事我。」子行夫婦的禮儀規程與道崇高德行與品性修養規範焉，沒身不衰。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 20 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子有二妾，父母愛一人焉，子愛一人焉，由衣服飲食，由執事，毋敢視父母所愛，雖父母沒不衰」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子有二妾，父母愛一人焉，子愛一人焉，由衣服飲食，由執……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-21\",\"chapterId\":\"li-ji_ch-12\",\"order\":21,\"canonicalText\":\"父母雖沒，將為善，思貽父母令名，必果；將為不善，思貽父母羞辱，必不果。\",\"sentenceIds\":[\"li-ji_ch-12_p-21_s-1\",\"li-ji_ch-12_p-21_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"父母親長縱然已經辭世，為人子女若將要立身行善，想到此舉能給已故父母帶來美好名聲，便必定堅決貫徹去施行；若心生邪念將要做不善之事，想到此舉必將使已故父母蒙受羞辱玷污，便必定斷然止步、絕不付諸實行！\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 21 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「父母雖沒，將為善，思貽父母令名，必果」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「父母雖沒，將為善，思貽父母令名，必果；將為不善，思貽……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-22\",\"chapterId\":\"li-ji_ch-12\",\"order\":22,\"canonicalText\":\"舅沒則姑老，冢婦所祭祀、賓客，每事必請於姑，介婦請於冢婦。舅姑使冢婦，毋怠，不友無禮於介婦。舅姑若使介婦，毋敢敵耦於冢婦，不敢並行，不敢並命，不敢並坐。\",\"sentenceIds\":[\"li-ji_ch-12_p-22_s-1\",\"li-ji_ch-12_p-22_s-2\",\"li-ji_ch-12_p-22_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"公公去世之後，婆婆年事已高退居老婦之位稱為「姑老」，此時主持家中宗族祭祀、接待賓客的重任由嫡長媳「冢婦」承擔，但凡事無大小依然必須每事先行請示稟報婆婆裁定，庶出的眾媳婦「介婦」則要向長媳冢婦請教遵行。公婆若差遣差使嫡長媳，長媳必須毫不怠惰恪盡職守，但絕不可仗恃長媳地位而對庶媳有傲慢不友愛無禮之舉。公婆若是差遣差使庶媳，庶媳絕不敢自矜其寵而與長媳互相攀比匹敵，行走時不敢與長媳並排行走，發布使令時不敢與長媳齊平發令，坐下時不敢與長媳並肩平起平坐。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 22 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「舅沒則姑老，冢婦所祭祀、賓客，每事必請於姑，介婦請於冢婦」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「舅沒則姑老，冢婦所祭祀、賓客，每事必請於姑，介婦請於……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-23\",\"chapterId\":\"li-ji_ch-12\",\"order\":23,\"canonicalText\":\"凡婦，不命適私室，不敢退。婦將有事，大小必請於舅姑。子婦無私貨，無私畜，無私器，不敢私假，不敢私與。婦或賜之飲食、衣服、布帛、佩帨、茝蘭，則受而獻諸舅姑，舅姑受之則喜，如新受賜，若反賜之則辭，不得命，如更受賜，藏以待乏。婦若有私親兄弟將與之，則必復請其故，賜而後與之。\",\"sentenceIds\":[\"li-ji_ch-12_p-23_s-1\",\"li-ji_ch-12_p-23_s-2\",\"li-ji_ch-12_p-23_s-3\",\"li-ji_ch-12_p-23_s-4\",\"li-ji_ch-12_p-23_s-5\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡是作為兒媳的女子，若無公婆的特意吩咐允許其退回自己的私室休息，絕不敢擅自擅自退席離去。兒媳將要操辦任何事情，無論事大事小都必須首先請示公婆定奪。做兒子的與做兒媳的，在家中不得擁有私自藏匿的財產貨物，不得擁有私自蓄養的牲畜家禽，不得擁有私自獨佔的器物器具，不敢私自向外人借用借貸，也不敢私自將家中之物借贈與外人。兒媳若是獲得娘家或外人賞賜餽贈的珍饈飲食、各色衣服、錦繡布帛、佩巾飾物、香草茝蘭，都必須敬謹收下並全數呈獻進獻給公婆；公婆若是賞臉收納了這些禮物，兒媳便如同自己再次榮獲長輩賞賜一般欣喜雀躍；公婆若是體恤兒媳而將所獻之物回賜給她，兒媳應當首先謙遜推辭辭謝，若公婆堅持賞賜而推辭不得，兒媳方才如同重新受領恩賜一般恭敬收下，並妥善珍藏起來，以備日後公婆庫存匱乏時隨時取出品奉。兒媳若是想將財物救濟饋贈給自己娘家的親戚弟兄，必須預先將詳情原委如實向公婆稟報請示，獲得公婆的同意恩准並親自賞賜之後，方才可以將財物轉贈給娘家親眷。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 23 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡婦，不命適私室，不敢退」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡婦，不命適私室，不敢退。婦將有事，大小必請於舅姑。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-24\",\"chapterId\":\"li-ji_ch-12\",\"order\":24,\"canonicalText\":\"適子庶子只事宗子宗婦。雖貴富，不敢以貴富入宗子之家，雖眾車徒舍於外，以寡約入。\",\"sentenceIds\":[\"li-ji_ch-12_p-24_s-1\",\"li-ji_ch-12_p-24_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"嫡出的次子與諸多庶出的支子，必須全心全意恭敬侍奉宗族的大宗繼承人「宗子」及其正妻「宗婦」。這些支子即便在外做官位極卿相、家財萬貫富比王侯，也絕不敢依仗自己的尊貴與富有傲慢步入宗子之門；即便隨身護衛的車馬侍從極其眾多，也必須全數留在宗子宅門之外駐紮，自己僅帶極少數隨從、衣著樸素謙約地步入宗子家中行宗族之禮。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 24 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「適子庶子只事宗子宗婦」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「適子庶子只事宗子宗婦。雖貴富，不敢以貴富入宗子之家，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-25\",\"chapterId\":\"li-ji_ch-12\",\"order\":25,\"canonicalText\":\"子弟猶歸器衣服裘衾車馬，則必獻其上，而後敢服用其次也；若非所獻，則不敢以入於宗子之門，不敢以貴富加於父兄宗族。若富，則具二牲，獻其賢者於宗子，夫婦皆齊而宗敬焉，終事而後敢私祭。\",\"sentenceIds\":[\"li-ji_ch-12_p-25_s-1\",\"li-ji_ch-12_p-25_s-2\",\"li-ji_ch-12_p-25_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子弟猶歸器衣服裘衾車馬，則必獻他的上，而且後敢服用他的次啊；若絕不是所獻，則不敢以入於宗子的門，不敢以貴富加於父兄宗族。若富，則具二牲，獻他的賢的人或禮儀規程與道崇高德行與品性修養規範制規範於宗子，夫婦皆齊而且宗敬焉，終事而且後敢私祭。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 25 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子弟猶歸器衣服裘衾車馬，則必獻其上，而後敢服用其次也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子弟猶歸器衣服裘衾車馬，則必獻其上，而後敢服用其次也……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-26\",\"chapterId\":\"li-ji_ch-12\",\"order\":26,\"canonicalText\":\"飯：黍，稷，稻，粱，白黍，黃粱，稰，穛。\",\"sentenceIds\":[\"li-ji_ch-12_p-26_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"古代貴族常備之主食五穀：包含黏黃米黍、不黏黃米稷、稻米、精選黃粱、白黍、優選黃粱，以及熟穀磨成之稰米與新收早稻之穛米等各種精細糧食。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 26 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「飯：黍，稷，稻，粱，白黍，黃粱，稰，穛」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「飯：黍，稷，稻，粱，白黍，黃粱，稰，穛。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-27\",\"chapterId\":\"li-ji_ch-12\",\"order\":27,\"canonicalText\":\"膳：膷，臐，膮，醢，牛炙。醢，牛胾，醢，牛膾。羊炙，羊胾，醢，豕炙。醢，豕胾，芥醬，魚膾。雉，兔，鶉，鷃。\",\"sentenceIds\":[\"li-ji_ch-12_p-27_s-1\",\"li-ji_ch-12_p-27_s-2\",\"li-ji_ch-12_p-27_s-3\",\"li-ji_ch-12_p-27_s-4\",\"li-ji_ch-12_p-27_s-5\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"常設之宴饗菜餚肉膳：有帶蔥調味的牛羊肉羹（膷）、加薑之肉羹（臐）、五味俱全之濃肉湯（膮）、肉醬醢汁，以及烤牛肉串；牛肉醬搭配切片大塊牛肉，肉醬佐以生切牛肉膾；烤羊肉串配大塊羊肉，肉醬佐以烤豬肉串；肉醬搭配大塊豬肉，以芥末辛辣之醬調配生魚膾片；此外常備野雞、野兔、鵪鶉與鷃雀等飛禽珍饈。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 27 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「膳：膷，臐，膮，醢，牛炙」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「膳：膷，臐，膮，醢，牛炙。醢，牛胾，醢，牛膾。羊炙，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-28\",\"chapterId\":\"li-ji_ch-12\",\"order\":28,\"canonicalText\":\"飲：重醴，稻醴清糟，黍醴清糟，粱醴清糟，或以酏為醴，黍酏，漿，水，醷，濫。\",\"sentenceIds\":[\"li-ji_ch-12_p-28_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"常設之日常飲品：有過濾兩次的醇厚重醴、稻米甜酒（有清液有酒糟）、黍米甜酒、粱米甜酒，或者以稀粥薄糜發酵製成之醴酒，以及黍米薄粥、酸漿、甘泉清泉、梅李調製之酸飲醷漿，以及瓜果浸泡之涼飲濫水。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 28 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「飲：重醴，稻醴清糟，黍醴清糟，粱醴清糟，或以酏為醴，黍酏，漿，水，醷，濫」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「飲：重醴，稻醴清糟，黍醴清糟，粱醴清糟，或以酏為醴，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-29\",\"chapterId\":\"li-ji_ch-12\",\"order\":29,\"canonicalText\":\"酒：清、白。\",\"sentenceIds\":[\"li-ji_ch-12_p-29_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"酒：清、白。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 29 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「酒：清、白」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「酒：清、白。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-30\",\"chapterId\":\"li-ji_ch-12\",\"order\":30,\"canonicalText\":\"羞：糗，餌，粉，酏。\",\"sentenceIds\":[\"li-ji_ch-12_p-30_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"羞：糗，餌，粉，酏。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 30 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「羞：糗，餌，粉，酏」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「羞：糗，餌，粉，酏。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-31\",\"chapterId\":\"li-ji_ch-12\",\"order\":31,\"canonicalText\":\"食：蝸醢而菰食，雉羹；麥食，脯羹，雞羹；析稌，犬羹，兔羹；和糝不蓼。\",\"sentenceIds\":[\"li-ji_ch-12_p-31_s-1\",\"li-ji_ch-12_p-31_s-2\",\"li-ji_ch-12_p-31_s-3\",\"li-ji_ch-12_p-31_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"古代貴族宴飲的食材搭配之道：吃蝸牛濃醬（蝸醢）時應當搭配清香的雕胡菰米飯，並佐以鮮美的野雉肉羹；吃麥粒麥飯時，應當搭配乾肉脯烹製的脯羹與鮮嫩的雞肉羹；吃精細淘洗的稻米飯（析稌）時，應當搭配溫補的狗肉羹與清鮮的兔肉羹；凡是用米屑米粉調和肉末製成的「糝羹」，烹飪時一律不放辛辣的蓼草以保其甘醇本味。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 31 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「食：蝸醢而菰食，雉羹」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「食：蝸醢而菰食，雉羹；麥食，脯羹，雞羹；析稌，犬羹，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-32\",\"chapterId\":\"li-ji_ch-12\",\"order\":32,\"canonicalText\":\"濡豚，包苦實蓼；濡雞，醢醬實蓼；濡魚，卵醬實蓼；濡鱉，醢醬實蓼。\",\"sentenceIds\":[\"li-ji_ch-12_p-32_s-1\",\"li-ji_ch-12_p-32_s-2\",\"li-ji_ch-12_p-32_s-3\",\"li-ji_ch-12_p-32_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"烹製各類鮮美肉類之古法調配：烹調乳豬，外包苦菜、內部填塞蓼草香料；烹調鮮雞，蘸以肉醬、內部填塞蓼草；烹煮鮮魚，以魚卵之醬調味、內填蓼草；烹燉水鱉，蘸以肉醬、腹內填塞蓼草去腥提鮮。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 32 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「濡豚，包苦實蓼」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「濡豚，包苦實蓼；濡雞，醢醬實蓼；濡魚，卵醬實蓼；濡鱉……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-33\",\"chapterId\":\"li-ji_ch-12\",\"order\":33,\"canonicalText\":\"腶修，蚳醢，脯羹，兔醢，糜膚，魚醢，魚膾，芥醬，麋腥，醢，醬，桃諸，梅諸，卵鹽。\",\"sentenceIds\":[\"li-ji_ch-12_p-33_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"精美脯醢與果品佐料之陳列：有厚切肉乾（腶脩）、螞蟻卵醬（蚳醢）、肉乾濃羹、兔肉泥醬、麋鹿皮凍肉片、魚肉醬、生魚膾片、辛辣芥醬、生麋鹿鮮肉，搭配濃醬、桃子果乾、烏梅果脯，以及粗粒海鹽等精美調味。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 33 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「腶修，蚳醢，脯羹，兔醢，糜膚，魚醢，魚膾，芥醬，麋腥，醢，醬，桃諸，梅諸，卵鹽」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「腶修，蚳醢，脯羹，兔醢，糜膚，魚醢，魚膾，芥醬，麋腥……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-34\",\"chapterId\":\"li-ji_ch-12\",\"order\":34,\"canonicalText\":\"凡食齊視春時，羹齊視夏時，醬齊視秋時，飲齊視冬時。\",\"sentenceIds\":[\"li-ji_ch-12_p-34_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"烹調飲食之四時火候與調配法度：凡飯食穀物之乾濕軟硬應當順應春季溫潤之氣，熬製肉羹之濃淡應當順應夏季陽盛之氣，調配各色肉醬應當順應秋季收斂之氣，調製冷熱酒飲應當順應冬季閉藏之氣。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 34 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡食齊視春時，羹齊視夏時，醬齊視秋時，飲齊視冬時」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡食齊視春時，羹齊視夏時，醬齊視秋時，飲齊視冬時。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-35\",\"chapterId\":\"li-ji_ch-12\",\"order\":35,\"canonicalText\":\"凡和，春多酸，夏多苦，秋多辛，冬多鹹，調以滑甘。\",\"sentenceIds\":[\"li-ji_ch-12_p-35_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"五味調和之四時養生法則：春季調味宜略多酸味以養肝氣，夏季調味宜略多苦味以養心氣，秋季調味宜略多辛辣以潤肺氣，冬季調味宜略多鹹味以固腎氣，並以甘滑甜潤之佐料調和諸味使其平和醇厚。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 35 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡和，春多酸，夏多苦，秋多辛，冬多鹹，調以滑甘」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡和，春多酸，夏多苦，秋多辛，冬多鹹，調以滑甘。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-36\",\"chapterId\":\"li-ji_ch-12\",\"order\":36,\"canonicalText\":\"牛宜稌，羊宜黍，豕宜稷，犬宜粱，雁宜麥，魚宜菰。\",\"sentenceIds\":[\"li-ji_ch-12_p-36_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"肉食與五穀糧食之相配宜忌：吃牛肉最適宜搭配稻米稌飯，吃羊肉最適宜搭配黃米黍飯，吃豬肉最適宜搭配稷穀小米，吃犬肉最適宜搭配黃粱飯，吃野雁之肉最適宜搭配麥飯，吃魚肉最適宜搭配茭白雕菰之飯。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 36 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「牛宜稌，羊宜黍，豕宜稷，犬宜粱，雁宜麥，魚宜菰」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「牛宜稌，羊宜黍，豕宜稷，犬宜粱，雁宜麥，魚宜菰。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-37\",\"chapterId\":\"li-ji_ch-12\",\"order\":37,\"canonicalText\":\"春宜羔豚膳膏薌，夏宜腒鱐膳膏臊，秋宜犢麑膳膏腥，冬宜鮮羽膳膏羶。\",\"sentenceIds\":[\"li-ji_ch-12_p-37_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"四季膳食肉類與油脂配伍宜忌：春季宜食羊羔乳豬配以牛脂煎調之香油；夏季宜食風乾肉與乾魚片配以犬膏煎熬之臊油；秋季宜食小牛犢與幼鹿肉配以豬膏煎熬之腥油；冬季宜食鮮魚飛禽配以羊油煎熬之羶油，以此順應陰陽之調。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 37 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「春宜羔豚膳膏薌，夏宜腒鱐膳膏臊，秋宜犢麑膳膏腥，冬宜鮮羽膳膏羶」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「春宜羔豚膳膏薌，夏宜腒鱐膳膏臊，秋宜犢麑膳膏腥，冬宜……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-38\",\"chapterId\":\"li-ji_ch-12\",\"order\":38,\"canonicalText\":\"牛修，鹿脯，田豕脯，糜脯，麇脯，麋、鹿、田豕、麇，皆有軒，雉兔皆有芼。爵，鷃，蜩，範，芝栭，菱，椇，棗，栗，榛，柿，瓜，桃，李，梅，杏，楂，梨，姜，桂。\",\"sentenceIds\":[\"li-ji_ch-12_p-38_s-1\",\"li-ji_ch-12_p-38_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"備製之各式乾肉脯與時令果品：有牛肉乾、鹿肉脯、野豬肉脯、麋肉脯、麇肉脯；麋、鹿、野豬、麇肉皆切成大片厚脯，野雞野兔肉羹皆添加蔬菜芼草調味；禽鳥有麻雀、鷃鶉，昆蟲有鳴蟬、蜂蛹；菌類有木耳芝栭；果品有水菱、枳椇、紅棗、板栗、榛子、甜柿、甜瓜、蜜桃、李子、青梅、甜杏、山楂、雪梨，以及生薑與肉桂香料。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 38 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「牛修，鹿脯，田豕脯，糜脯，麇脯，麋、鹿、田豕、麇，皆有軒，雉兔皆有芼」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「牛修，鹿脯，田豕脯，糜脯，麇脯，麋、鹿、田豕、麇，皆……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-39\",\"chapterId\":\"li-ji_ch-12\",\"order\":39,\"canonicalText\":\"大夫燕食，有膾無脯，有脯無膾。士不貳羹胾，庶人耆老不徒食。\",\"sentenceIds\":[\"li-ji_ch-12_p-39_s-1\",\"li-ji_ch-12_p-39_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"卿大夫貴族官員燕食，有膾無脯，有脯無膾。士人階層不貳羹胾，平民百姓耆老不徒食。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 39 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「大夫燕食，有膾無脯，有脯無膾」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「大夫燕食，有膾無脯，有脯無膾。士不貳羹胾，庶人耆老不……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-40\",\"chapterId\":\"li-ji_ch-12\",\"order\":40,\"canonicalText\":\"膾：春用蔥，秋用芥、豚；春用韭，秋用蓼。脂用蔥，膏用薤，三牲用藙，和用醯，獸用梅。鶉羹、雞羹、鴽，釀之蓼。魴鱮烝，雛燒，雉，薌無蓼。\",\"sentenceIds\":[\"li-ji_ch-12_p-40_s-1\",\"li-ji_ch-12_p-40_s-2\",\"li-ji_ch-12_p-40_s-3\",\"li-ji_ch-12_p-40_s-4\",\"li-ji_ch-12_p-40_s-5\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"精細切製的生肉切片「膾」：春季應當佐以青蔥調味，秋季則應當佐以辛辣的芥子調味；烹調小豬小豚肉時，春季應當配以鮮韭，秋季則應當配以蓼草。料理有角獸類的硬脂時應當配以蔥，料理無角獸類的軟膏時應當配以薤白；烹煮牛羊豬三牲時用茱萸（藙）去腥提香，調和百味時用酸醋（醯），烹調各類野生獵獸時則用青梅梅酸調味。烹製鵪鶉肉羹、雞肉羹與鴽鳥肉羹時，肉餡內腹中要填塞釀入蓼葉蒸煮。烹調魴魚與鱮魚時要清蒸，烹調幼禽雛鳥時要火火燒烤，烹調野雉野雞時，只需加入芳香的紫蘇調香而切不可添加蓼菜。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 40 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「膾：春用蔥，秋用芥、豚」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「膾：春用蔥，秋用芥、豚；春用韭，秋用蓼。脂用蔥，膏用……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-41\",\"chapterId\":\"li-ji_ch-12\",\"order\":41,\"canonicalText\":\"不食雛鱉，狼去腸，狗去腎，貍去正脊，兔去尻，狐去首，豚去腦，魚去乙，鱉去醜。\",\"sentenceIds\":[\"li-ji_ch-12_p-41_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"宰殺烹割肉禽動物之衛生禁忌：不食用幼小稚嫩之雛鱉，屠宰野狼需剔除其腸臟，烹割狗肉需剔除其腎臟，烹割野狸需去除其正脊背肉，烹割野兔需切除尾部尻骨，烹宰野狐需剁去頭顱，烹殺幼豬需剔除腦髓，烹剖鮮魚需挑除膽腸乙骨，烹調大鱉需去除肛門穢物。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 41 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「不食雛鱉，狼去腸，狗去腎，貍去正脊，兔去尻，狐去首，豚去腦，魚去乙，鱉去醜」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「不食雛鱉，狼去腸，狗去腎，貍去正脊，兔去尻，狐去首，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-42\",\"chapterId\":\"li-ji_ch-12\",\"order\":42,\"canonicalText\":\"肉曰脫之，魚曰作之，棗曰新之，栗曰撰之，桃曰膽之，柤梨曰攢之。\",\"sentenceIds\":[\"li-ji_ch-12_p-42_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"肉說道：脫的，魚說道：作的，棗說道：新的，栗說道：撰的，桃說道：膽的，柤梨說道：攢的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 42 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「肉曰脫之，魚曰作之，棗曰新之，栗曰撰之，桃曰膽之，柤梨曰攢之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「肉曰脫之，魚曰作之，棗曰新之，栗曰撰之，桃曰膽之，柤……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-43\",\"chapterId\":\"li-ji_ch-12\",\"order\":43,\"canonicalText\":\"牛夜鳴則庮，羊泠毛而毳、羶，狗赤股而躁、臊，鳥麃色而沙鳴、鬱，豕望視而交睫、腥，馬黑脊而般臂、漏，雛尾不盈握弗食，舒雁翠，鵠鴞胖，舒鳧翠，雞肝，雁腎，鴇奧，鹿胃。\",\"sentenceIds\":[\"li-ji_ch-12_p-43_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"關於肉食衛生的辨別與進食禁忌：黃牛若是在夜間頻頻哀鳴悲叫，其肉必定發臭變質腐敗（稱為庮）；山羊若毛髮稀疏脫落且皮毛蓬亂，其肉必定腥羶難聞（羶）；犬隻若是大腿內側脫毛泛紅且煩躁狂跳，其肉必定燥烈腥臊（臊）；禽鳥若羽毛雜亂褪色且鳴聲沙啞枯澀，其肉必定鬱熱生毒（鬱）；生豬若是目光呆滯斜視且睫毛黏合交接，其肉必定帶有惡濁腥臭（腥）；戰馬若是脊背焦黑且前腿皮毛斑駁雜色，必定身患尿血淋漏之疾（漏）；各類幼禽雛鳥若是尾羽長度不足一握之寬，絕對不可宰殺食用；大雁的尾肉（翠）、天鵝與鶚鳥的肋肉（胖）、母鴨的尾肉、雄雞的內臟肝臟、野雁的雙腎、鴇鳥的內腹脾臟、以及野鹿的胃囊，皆因容易蓄積毒素或氣味極其腥濁而嚴禁食用。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 43 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「牛夜鳴則庮，羊泠毛而毳、羶，狗赤股而躁、臊，鳥麃色而沙鳴、鬱，豕望視而交睫、腥，馬黑脊而般臂、漏，雛尾不盈握弗食，舒雁翠，鵠鴞胖，舒鳧翠，雞肝，雁腎，鴇奧，鹿胃」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「牛夜鳴則庮，羊泠毛而毳、羶，狗赤股而躁、臊，鳥麃色而……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-44\",\"chapterId\":\"li-ji_ch-12\",\"order\":44,\"canonicalText\":\"肉腥細者為膾，大者為軒；或曰麋鹿魚為菹，麇為闢雞，野豕為軒，兔為宛脾，切蔥若薤，實諸醯以柔之。\",\"sentenceIds\":[\"li-ji_ch-12_p-44_s-1\",\"li-ji_ch-12_p-44_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"肉腥細的人或禮儀規程與道崇高德行與品性修養規範制規範為膾，大的人或禮儀規程與道崇高德行與品性修養規範制規範為軒；或說道：麋鹿魚為菹，麇為闢雞，野豕為軒，兔為宛脾，切蔥若薤，實諸醯以柔的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 44 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「肉腥細者為膾，大者為軒」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「肉腥細者為膾，大者為軒；或曰麋鹿魚為菹，麇為闢雞，野……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-45\",\"chapterId\":\"li-ji_ch-12\",\"order\":45,\"canonicalText\":\"羹食，自諸侯以下至於庶人無等。\",\"sentenceIds\":[\"li-ji_ch-12_p-45_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"羹食，自諸侯以下至於平民百姓無等。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 45 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「羹食，自諸侯以下至於庶人無等」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「羹食，自諸侯以下至於庶人無等。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-46\",\"chapterId\":\"li-ji_ch-12\",\"order\":46,\"canonicalText\":\"大夫無秩膳，大夫七十而有閣，天子之閣。左達五，右達五，公侯伯於房中五，大夫於閣三，士於坫一。\",\"sentenceIds\":[\"li-ji_ch-12_p-46_s-1\",\"li-ji_ch-12_p-46_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"卿大夫貴族官員無秩膳，卿大夫貴族官員七十而且有閣，天子的閣。左達五，右達五，公侯伯於房中五，卿大夫貴族官員於閣三，士人階層於坫一。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 46 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「大夫無秩膳，大夫七十而有閣，天子之閣」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「大夫無秩膳，大夫七十而有閣，天子之閣。左達五，右達五……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-47\",\"chapterId\":\"li-ji_ch-12\",\"order\":47,\"canonicalText\":\"凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人修而兼用之。凡五十養於鄉，六十養於國，七十養於學，達於諸侯。八十拜君命，一坐再至，瞽亦如之，九十者使人受。五十異粻，六十宿肉，七十二膳，八十常珍，九十飲食不違寢，膳飲從於遊可也。六十歲制，七十時制，八十月制，九十日修，唯絞紟衾冒，死而後制。五十始衰，六十非肉不飽，七十非帛不暖，八十非人不暖，九十雖得人不暖矣。五十杖於家，六十杖於鄉，七十杖於國，八十杖於朝，九十者天子欲有問焉，則就其室以珍從。七十不俟朝，八十月告存，九十日有秩。五十不從力政，六十不與服戎，七十不與賓客之事，八十齊喪之事弗及也。五十而爵，六十不親學，七十致政；凡自七十以上，唯衰麻為喪。\",\"sentenceIds\":[\"li-ji_ch-12_p-47_s-1\",\"li-ji_ch-12_p-47_s-2\",\"li-ji_ch-12_p-47_s-3\",\"li-ji_ch-12_p-47_s-4\",\"li-ji_ch-12_p-47_s-5\",\"li-ji_ch-12_p-47_s-6\",\"li-ji_ch-12_p-47_s-7\",\"li-ji_ch-12_p-47_s-8\",\"li-ji_ch-12_p-47_s-9\",\"li-ji_ch-12_p-47_s-10\",\"li-ji_ch-12_p-47_s-11\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡是古代奉養尊老之禮：有虞氏時代依照親睦的「燕禮」奉養老人，夏后氏時代依照豐盛的「饗禮」奉養老人，殷商時代依照莊重的「食禮」奉養老人，周代王朝則兼收並蓄將三代禮儀修整兼用。凡老人年滿五十歲在鄉學庠序中受養，年滿六十歲在國都小學中受養，年滿七十歲在天子太學辟雍中受養，這套敬老制度通達普及於天下各國諸侯。老人年滿八十歲拜受國君召命賞賜時，允許其跪坐一次而兩次叩頭至地以省勞頓，雙目失明的瞽者樂官亦同享此禮遇，年屆九十歲者則可差遣子孫代為前往受命。五十歲者口糧給予精良特供，六十歲者常備熟肉，七十歲者每餐雙倍副膳，八十歲者常供各類珍饈，九十歲者飲食起居不離寢榻之側，遊憩散步皆有專人帶著茶膳隨行侍奉。六十歲者每年修造一次壽具棺槨，七十歲者每季檢視一次，八十歲者每月修治一次，九十歲者每日維護整飭，唯獨束屍絞帶、裹屍衾被與套屍之冒，必須待老人真正壽終之後才能裁製。人到五十歲體魄始衰，六十歲非吃肉食不得飽足，七十歲非著絲帛不得溫暖，八十歲非有人同榻共寢暖身不得溫熱，九十歲則即便有人同寢亦難覺溫暖。五十歲允許拄杖行於家中，六十歲允許拄杖行於鄉里，七十歲允許拄杖行於國都大道，八十歲允許拄杖出入朝廷殿堂，老人年滿九十歲若天子有政務垂詢，天子親自前往老人家中登門請教並隨車攜帶珍味賞賜。七十歲者不必在朝中久立候朝，八十歲者朝廷每月派官慰問察存，九十歲者每日按律供給常奉膳食。五十歲免除各類重體力徭役，六十歲免除兵役從軍，七十歲免除繁雜的賓客應酬禮儀，八十歲連同齋戒奔喪的深重禮俗亦皆可豁免不臨。五十歲始可受封爵位，六十歲不再親自主持學務，七十歲致仕退休交還政柄；凡自七十歲以上的老人守喪，只需身穿衰麻喪服以示哀意即可，不拘泥於一切哀毀傷生的喪葬繁文。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 47 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人修而兼用之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-48\",\"chapterId\":\"li-ji_ch-12\",\"order\":48,\"canonicalText\":\"凡三王養老皆引年，八十者一子不從政，九十者其家不從政；瞽亦如之。凡父母在，子雖老不坐。有虞氏養國老於上庠，養庶老於下庠；夏后氏養國老於東序，養庶老於西序；殷人養國老於右學，養庶老於左學；周人養國老於東膠，養庶老於虞庠，虞庠在國之西郊。有虞氏皇而祭，深衣而養老；夏后氏收而祭，燕衣而養老；殷人冔而祭，縞衣而養老；周人冕而祭，玄衣而養老。\",\"sentenceIds\":[\"li-ji_ch-12_p-48_s-1\",\"li-ji_ch-12_p-48_s-2\",\"li-ji_ch-12_p-48_s-3\",\"li-ji_ch-12_p-48_s-4\",\"li-ji_ch-12_p-48_s-5\",\"li-ji_ch-12_p-48_s-6\",\"li-ji_ch-12_p-48_s-7\",\"li-ji_ch-12_p-48_s-8\",\"li-ji_ch-12_p-48_s-9\",\"li-ji_ch-12_p-48_s-10\",\"li-ji_ch-12_p-48_s-11\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡是夏、商、周三代聖王推行養老之禮，都要依照年歲壽數核算減免其家屬徭役：老人年滿八十歲者，朝廷免除其一個兒子的官府役作以便在家專心奉養；老人年滿九十歲者，朝廷免除其全體家族的人力徭役；雙目失明的盲人家境亦享受相同待遇。凡父母尚且健在之時，做兒子的即便自己已經年過六十衰老，在父母座前亦不敢隨便安坐以示孝敬。有虞氏時代在太學「上庠」奉養卿大夫致仕之國老，在西郊「下庠」奉養平民年長之庶老；夏后氏時代在太學「東序」奉養國老，在西學「西序」奉養庶老；殷商時代在西郊大學「右學」奉養國老，在東學「左學」奉養庶老；周王朝在東部大學「東膠」奉養國老，在西郊學校「虞庠」奉養庶老，虞庠正是座落於國都繁盛的西郊之境。有虞氏祭天頭戴飾有羽毛的皇冠，舉行養老禮時身穿樸素深衣；夏后氏祭祀頭戴端整收斂的黑布收冠，養老時身穿私居燕衣；殷商人祭祀頭戴覆額向下的白色冔冠，養老時身穿純白縞衣；周代人祭祀頭戴尊崇肅穆的十二旒冕冠，養老時則身穿尊貴高尚的黑色玄衣。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 48 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡三王養老皆引年，八十者一子不從政，九十者其家不從政」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡三王養老皆引年，八十者一子不從政，九十者其家不從政……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-49\",\"chapterId\":\"li-ji_ch-12\",\"order\":49,\"canonicalText\":\"曾子曰：「孝子之養老也，樂其心不違其志，樂其耳目，安其寢處，以其飲食忠養之孝子之身終，終身也者，非終父母之身，終其身也；是故父母之所愛亦愛之，父母之所敬亦敬之，至於犬馬盡然，而況於人乎！」\",\"sentenceIds\":[\"li-ji_ch-12_p-49_s-1\",\"li-ji_ch-12_p-49_s-2\",\"li-ji_ch-12_p-49_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"曾孔子先生親自開示教導說道：「孝子的養老啊，雅樂和聲與心靈感化他的心不違他的志，雅樂和聲與心靈感化他的耳目，安他的寢處，以他的飲食忠養的孝子的身終，終身啊的人或禮儀規程與道崇高德行與品性修養規範制規範，絕不是終父母的身，終他的身啊；正因為如此父母的所愛亦愛的，父母的所敬亦敬的，至於犬馬盡然，而且況於人乎！」。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 49 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「曾子曰：「孝子之養老也，樂其心不違其志，樂其耳目，安其寢處，以其飲食忠養之孝子之身終，終身也者，非終父母之身，終其身也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「曾子曰：「孝子之養老也，樂其心不違其志，樂其耳目，安……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-50\",\"chapterId\":\"li-ji_ch-12\",\"order\":50,\"canonicalText\":\"凡養老，五帝憲，三王有乞言。五帝憲，養氣體而不乞言，有善則記之為惇史。三王亦憲，既養老而後乞言，亦微其禮，皆有惇史。\",\"sentenceIds\":[\"li-ji_ch-12_p-50_s-1\",\"li-ji_ch-12_p-50_s-2\",\"li-ji_ch-12_p-50_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡養老，五帝憲，三王有乞言。五帝憲，養氣體而且不乞言，有善則記的為惇史。三王亦憲，既養老而且後乞言，亦微他的禮儀規程與道崇高德行與品性修養規範，皆有惇史。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 50 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡養老，五帝憲，三王有乞言」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡養老，五帝憲，三王有乞言。五帝憲，養氣體而不乞言，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-51\",\"chapterId\":\"li-ji_ch-12\",\"order\":51,\"canonicalText\":\"淳熬：煎醢，加於陸稻上，沃之以膏曰淳熬。淳毋煎醢，加於黍食上，沃之以膏曰淳毋。\",\"sentenceIds\":[\"li-ji_ch-12_p-51_s-1\",\"li-ji_ch-12_p-51_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"淳熬：煎醢，加於陸稻上，沃的以膏說道：淳熬。淳毋煎醢，加於黍食上，沃的以膏說道：淳毋。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 51 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「淳熬：煎醢，加於陸稻上，沃之以膏曰淳熬」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「淳熬：煎醢，加於陸稻上，沃之以膏曰淳熬。淳毋煎醢，加……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-52\",\"chapterId\":\"li-ji_ch-12\",\"order\":52,\"canonicalText\":\"炮：取豚若將，刲之刳之，實棗於其腹中，編萑以苴之，塗之以謹塗，炮之，塗皆乾，擘之，濯手以摩之，去其皽，為稻粉糔溲之以為酏，以付豚煎諸膏，膏必滅之，鉅鑊湯以小鼎薌脯於其中，使其湯毋滅鼎，三日三夜毋絕火，而後調之以醯醢。\",\"sentenceIds\":[\"li-ji_ch-12_p-52_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"炮：取豚若將，刲的刳的，實棗於他的腹中，編萑以苴的，塗的以謹塗，炮的，塗皆乾，擘的，濯手以摩的，去他的皽，為稻粉糔溲的以為酏，以付豚煎諸膏，膏必滅的，鉅鑊湯以小鼎薌脯於他的中，使他的湯毋滅鼎，三日三夜毋絕火，而且後調的以醯醢。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 52 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「炮：取豚若將，刲之刳之，實棗於其腹中，編萑以苴之，塗之以謹塗，炮之，塗皆乾，擘之，濯手以摩之，去其皽，為稻粉糔溲之以為酏，以付豚煎諸膏，膏必滅之，鉅鑊湯以小鼎薌脯於其中，使其湯毋滅鼎，三日三夜毋絕火，而後調之以醯醢」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「炮：取豚若將，刲之刳之，實棗於其腹中，編萑以苴之，塗……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-53\",\"chapterId\":\"li-ji_ch-12\",\"order\":53,\"canonicalText\":\"搗珍：取牛羊麋鹿麇之肉必脄，每物與牛若一捶，反側之，去其餌，熟出之，去其餌，柔其肉。\",\"sentenceIds\":[\"li-ji_ch-12_p-53_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"搗珍：取牛羊麋鹿麇的肉必脄，每物與牛若一捶，反側的，去他的餌，熟出的，去他的餌，柔他的肉。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 53 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「搗珍：取牛羊麋鹿麇之肉必脄，每物與牛若一捶，反側之，去其餌，熟出之，去其餌，柔其肉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「搗珍：取牛羊麋鹿麇之肉必脄，每物與牛若一捶，反側之，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-54\",\"chapterId\":\"li-ji_ch-12\",\"order\":54,\"canonicalText\":\"漬：取牛肉必新殺者，薄切之，必絕其理；湛諸美酒，期朝而食之以醢若醯醷。\",\"sentenceIds\":[\"li-ji_ch-12_p-54_s-1\",\"li-ji_ch-12_p-54_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"漬：取牛肉必新殺的人或禮儀規程與道崇高德行與品性修養規範制規範，薄切的，必絕他的理；湛諸美酒，期朝而且食的以醢若醯醷。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 54 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「漬：取牛肉必新殺者，薄切之，必絕其理」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「漬：取牛肉必新殺者，薄切之，必絕其理；湛諸美酒，期朝……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-55\",\"chapterId\":\"li-ji_ch-12\",\"order\":55,\"canonicalText\":\"為熬：捶之，去其皽，編萑布牛肉焉，屑桂與姜以灑諸上而鹽之，乾而食之。施羊亦如之，施麋、施鹿、施麇皆如牛羊。欲濡肉則釋而煎之以醢，欲乾肉則捶而食之。\",\"sentenceIds\":[\"li-ji_ch-12_p-55_s-1\",\"li-ji_ch-12_p-55_s-2\",\"li-ji_ch-12_p-55_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"為熬：捶的，去他的皽，編萑布牛肉焉，屑桂與姜以灑諸上而且鹽的，乾而且食的。施羊亦如的，施麋、施鹿、施麇皆如牛羊。欲濡肉則釋而且煎的以醢，欲乾肉則捶而且食的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 55 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「為熬：捶之，去其皽，編萑布牛肉焉，屑桂與姜以灑諸上而鹽之，乾而食之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「為熬：捶之，去其皽，編萑布牛肉焉，屑桂與姜以灑諸上而……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-56\",\"chapterId\":\"li-ji_ch-12\",\"order\":56,\"canonicalText\":\"糝：取牛羊豕之肉，三如一小切之，與稻米；稻米二肉一，合以為餌煎之。\",\"sentenceIds\":[\"li-ji_ch-12_p-56_s-1\",\"li-ji_ch-12_p-56_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"糝：取牛羊豕的肉，三如一小切的，與稻米；稻米二肉一，合以為餌煎的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 56 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「糝：取牛羊豕之肉，三如一小切之，與稻米」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「糝：取牛羊豕之肉，三如一小切之，與稻米；稻米二肉一，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-57\",\"chapterId\":\"li-ji_ch-12\",\"order\":57,\"canonicalText\":\"肝菺：取狽肝一，幪之，以其菺濡炙之，舉焦，其菺不蓼；取稻米舉糔溲之，小切狼臅膏，以與稻米為酏。\",\"sentenceIds\":[\"li-ji_ch-12_p-57_s-1\",\"li-ji_ch-12_p-57_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"肝菺：取狽肝一，幪的，以他的菺濡炙的，舉焦，他的菺不蓼；取稻米舉糔溲的，小切狼臅膏，以與稻米為酏。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 57 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「肝菺：取狽肝一，幪之，以其菺濡炙之，舉焦，其菺不蓼」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「肝菺：取狽肝一，幪之，以其菺濡炙之，舉焦，其菺不蓼；……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-58\",\"chapterId\":\"li-ji_ch-12\",\"order\":58,\"canonicalText\":\"禮，始於謹夫婦，為宮室，辨外內。男子居外，女子居內，深宮固門，閽寺守之。男不入，女不出。\",\"sentenceIds\":[\"li-ji_ch-12_p-58_s-1\",\"li-ji_ch-12_p-58_s-2\",\"li-ji_ch-12_p-58_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"人類文明禮節制度的樹立，根本起始於審慎端正夫妻名分，進而營造宮室宅邸，嚴格辨別家庭內部與外部的界限。男子居於外宅處理政務農商，女子居於內室主持紡織家務，內院深邃而門禁堅固，由閽人閹寺負責晝夜嚴密把守門戶。男子無故不得擅自步入內宅，女子無故不得擅自走出閨門，以端肅家風正倫理之本。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 58 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「禮，始於謹夫婦，為宮室，辨外內」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「禮，始於謹夫婦，為宮室，辨外內。男子居外，女子居內，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-59\",\"chapterId\":\"li-ji_ch-12\",\"order\":59,\"canonicalText\":\"男女不同椸枷，不敢懸於夫之楎椸，不敢藏於夫之篋笥，不敢共湢浴。夫不在，斂枕篋簟席、襡器而藏之。少事長，賤事貴，鹹如之。\",\"sentenceIds\":[\"li-ji_ch-12_p-59_s-1\",\"li-ji_ch-12_p-59_s-2\",\"li-ji_ch-12_p-59_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"男女不同椸枷，不敢懸於夫的楎椸，不敢藏於夫的篋笥，不敢共湢浴。夫不在，斂枕篋簟席、襡器而且藏的。少事長，賤事貴，鹹如的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 59 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「男女不同椸枷，不敢懸於夫之楎椸，不敢藏於夫之篋笥，不敢共湢浴」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「男女不同椸枷，不敢懸於夫之楎椸，不敢藏於夫之篋笥，不……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-60\",\"chapterId\":\"li-ji_ch-12\",\"order\":60,\"canonicalText\":\"夫婦之禮，唯及七十，同藏無間。故妾雖老，年未滿五十，必與五日之御。將御者，齊，漱浣，慎衣服，櫛縰笄，總角，拂髦，衿纓綦屨。雖婢妾，衣服飲食必後長者。妻不在，妾御莫敢當夕。\",\"sentenceIds\":[\"li-ji_ch-12_p-60_s-1\",\"li-ji_ch-12_p-60_s-2\",\"li-ji_ch-12_p-60_s-3\",\"li-ji_ch-12_p-60_s-4\",\"li-ji_ch-12_p-60_s-5\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夫婦的禮儀規程與道崇高德行與品性修養規範，唯及七十，同藏無間。所以妾雖老，年未滿五十，必與五日的御。將御的人或禮儀規程與道崇高德行與品性修養規範制規範，齊，漱浣，慎衣服，櫛縰笄，總角，拂髦，衿纓綦屨。雖婢妾，衣服飲食必後長的人或禮儀規程與道崇高德行與品性修養規範制規範。妻不在，妾御莫敢當夕。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 60 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫婦之禮，唯及七十，同藏無間」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫婦之禮，唯及七十，同藏無間。故妾雖老，年未滿五十，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-61\",\"chapterId\":\"li-ji_ch-12\",\"order\":61,\"canonicalText\":\"妻將生子，及月辰，居側室，夫使人日再問之，作而自問之，妻不敢見，使姆衣服而對，至於子生，夫復使人日再問之，夫齊則不入側室之門。子生，男子設弧於門左，女子設帨於門右。三日，始負子，男射女否。\",\"sentenceIds\":[\"li-ji_ch-12_p-61_s-1\",\"li-ji_ch-12_p-61_s-2\",\"li-ji_ch-12_p-61_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"妻子即將分娩生產之際，到了臨產月份與產期，便移居到側室偏房之中；丈夫每日派遣侍者兩次前去探問問候安康；妻子若臨產陣痛起坐，丈夫親自前往探望，妻子依照禮法避嫌不敢當面相見，指派資深女師女姆穿戴端正代為出面應對回覆；及至嬰兒順利降生之後，丈夫再度派遣侍者每日兩度探問安危；若是丈夫正逢舉行齋戒祭祀神明之期，則不可跨入產婦側室之門。嬰兒降生之後，若是生下男嬰，便在寢門左側掛上一把桑木木弓（弧），以示日後當習武射御保家衛國；若是生下女嬰，便在寢門右側掛上一方佩巾手帕（帨），以示日後當溫良勤勉治家紡績。到了第三天，始由侍母正式抱起嬰兒，若是男孩便舉行抱子射天地四方的習射典禮，若是女孩則不舉行射禮。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 61 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「妻將生子，及月辰，居側室，夫使人日再問之，作而自問之，妻不敢見，使姆衣服而對，至於子生，夫復使人日再問之，夫齊則不入側室之門」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「妻將生子，及月辰，居側室，夫使人日再問之，作而自問之……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-62\",\"chapterId\":\"li-ji_ch-12\",\"order\":62,\"canonicalText\":\"國君世子生，告於君，接以大牢，宰掌具。三日，卜士負之，吉者宿齊朝服寢門外，詩負之，射人以桑弧蓬矢六。射天地四方，保受乃負之，宰醴負子，賜之束帛，卜士之妻、大夫之妾，使食子。\",\"sentenceIds\":[\"li-ji_ch-12_p-62_s-1\",\"li-ji_ch-12_p-62_s-2\",\"li-ji_ch-12_p-62_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"國君世子生，告於君，接以大牢，宰掌具。三日，卜士人階層負的，吉的人或禮儀規程與道崇高德行與品性修養規範制規範宿齊朝服寢門外，詩負的，射人以桑弧蓬矢六。射天地四方，保受乃負的，宰醴負子，賜的束帛，卜士人階層的妻、卿大夫貴族官員的妾，使食子。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 62 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「國君世子生，告於君，接以大牢，宰掌具」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「國君世子生，告於君，接以大牢，宰掌具。三日，卜士負之……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-63\",\"chapterId\":\"li-ji_ch-12\",\"order\":63,\"canonicalText\":\"凡接子，擇日，冢子則大牢，庶人特豚，士特豕，大夫少牢，國君世子大牢，其非冢子，則皆降一等。\",\"sentenceIds\":[\"li-ji_ch-12_p-63_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡接子，擇日，冢子則大牢，平民百姓特豚，士人階層特豕，卿大夫貴族官員少牢，國君世子大牢，他的絕不是冢子，則皆降一等。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 63 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡接子，擇日，冢子則大牢，庶人特豚，士特豕，大夫少牢，國君世子大牢，其非冢子，則皆降一等」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡接子，擇日，冢子則大牢，庶人特豚，士特豕，大夫少牢……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-64\",\"chapterId\":\"li-ji_ch-12\",\"order\":64,\"canonicalText\":\"異為孺子室於宮中，擇於諸母與可者，必求其寬裕慈惠、溫良恭敬、慎而寡言者，使為子師，其次為慈母，其次為保母，皆居子室，他人無事不往。\",\"sentenceIds\":[\"li-ji_ch-12_p-64_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"異為孺子室於宮中，擇於諸母與可的人或禮儀規程與道崇高德行與品性修養規範制規範，必求他的寬裕慈惠、溫良恭敬、慎而且寡言的人或禮儀規程與道崇高德行與品性修養規範制規範，使為子師，他的次為慈母，他的次為保母，皆居子室，他人無事不往。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 64 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「異為孺子室於宮中，擇於諸母與可者，必求其寬裕慈惠、溫良恭敬、慎而寡言者，使為子師，其次為慈母，其次為保母，皆居子室，他人無事不往」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「異為孺子室於宮中，擇於諸母與可者，必求其寬裕慈惠、溫……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-65\",\"chapterId\":\"li-ji_ch-12\",\"order\":65,\"canonicalText\":\"三月之末，擇日剪發為鬌，男角女羈，否則男左女右。是日也，妻以子見於父，貴人則為衣服，由命士以下，皆漱浣，男女夙興，沐浴衣服，具視朔食，夫入門，升自阼階。立於阼西鄉，妻抱子出自房，當楣立東面。\",\"sentenceIds\":[\"li-ji_ch-12_p-65_s-1\",\"li-ji_ch-12_p-65_s-2\",\"li-ji_ch-12_p-65_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在嬰兒出生滿三個月的月末之時，挑選吉日為孩子剃去部分胎髮挽成髮髻（稱為鬌），男孩在頭頂左右挽成兩角小髻，女孩則挽成盤繞環狀的羈髻；或者男孩保留左側頭髮，女孩保留右側頭髮以別性別。到了這一天，母親親自抱著嬰兒前往正堂拜見父親；貴族士大夫以上的人家專門為嬰兒裁製嶄新禮服，身受命爵的下士以下人家，則將現有衣服徹底浸洗浣滌潔淨；天明男女主人皆清晨早起，沐浴更衣換穿端整禮服，廚房備妥如同每月初一朔日宴飲一般的豐盛膳食；丈夫步入大門，從東面阼階登上堂屋，站在阼階頂端面向西站立；妻子抱著盛裝的嬰兒從內室房中走出，恰好正對著堂屋的正樑門楣面向東肅立。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 65 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「三月之末，擇日剪發為鬌，男角女羈，否則男左女右」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「三月之末，擇日剪發為鬌，男角女羈，否則男左女右。是日……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-66\",\"chapterId\":\"li-ji_ch-12\",\"order\":66,\"canonicalText\":\"姆先，相曰：「母某敢用時日只見孺子。」夫對曰：「欽有帥。」父執子之右手，咳而名之。妻對曰：「記有成。」遂左還，授師，子師辯告諸婦諸母名，妻遂適寢。\",\"sentenceIds\":[\"li-ji_ch-12_p-66_s-1\",\"li-ji_ch-12_p-66_s-2\",\"li-ji_ch-12_p-66_s-3\",\"li-ji_ch-12_p-66_s-4\",\"li-ji_ch-12_p-66_s-5\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"姆先，相說道：「母某敢用時日只見孺子。」夫對說道：「欽有帥。」父執子的右手，咳而且名的。妻對說道：「記有成。」遂左還，授師，子師辯告諸婦諸母名，妻遂適寢。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 66 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「姆先，相曰：「母某敢用時日只見孺子」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「姆先，相曰：「母某敢用時日只見孺子。」夫對曰：「欽有……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-67\",\"chapterId\":\"li-ji_ch-12\",\"order\":67,\"canonicalText\":\"夫告宰名，宰辯告諸男名，書曰：「某年某月某日某生。」而藏之，宰告閭史，閭史書為二，其一藏諸閭府，其一獻諸州史；州史獻諸州伯，州伯命藏諸州府。夫入食如養禮。\",\"sentenceIds\":[\"li-ji_ch-12_p-67_s-1\",\"li-ji_ch-12_p-67_s-2\",\"li-ji_ch-12_p-67_s-3\",\"li-ji_ch-12_p-67_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夫告宰名，宰辯告諸男名，書說道：「某年某月某日某生。」而且藏的，宰告閭史，閭史書為二，他的一藏諸閭府，他的一獻諸州史；州史獻諸州伯，州伯命藏諸州府。夫入食如養禮儀規程與道崇高德行與品性修養規範。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 67 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫告宰名，宰辯告諸男名，書曰：「某年某月某日某生」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫告宰名，宰辯告諸男名，書曰：「某年某月某日某生。」……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-68\",\"chapterId\":\"li-ji_ch-12\",\"order\":68,\"canonicalText\":\"世子生，則君沐浴朝服，夫人亦如之，皆立於阼階西鄉，世婦抱子升自西階，君名之，乃降。\",\"sentenceIds\":[\"li-ji_ch-12_p-68_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"國君的法定繼承人「世子」誕生之後，國君親自齋戒沐浴換穿隆重盛大的朝服，君夫人亦同樣沐浴梳妝換穿盛大禮服，夫婦二人一同肅立於殿堂東側的阼階頂端面向西方；主管宮嬪的女官「世婦」小心翼翼抱著世子從西側賓階徐徐登上堂前；國君親口為世子正式命名，世子命名典禮完成之後，世婦方才抱著世子從西階緩緩降下退堂。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 68 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「世子生，則君沐浴朝服，夫人亦如之，皆立於阼階西鄉，世婦抱子升自西階，君名之，乃降」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「世子生，則君沐浴朝服，夫人亦如之，皆立於阼階西鄉，世……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-69\",\"chapterId\":\"li-ji_ch-12\",\"order\":69,\"canonicalText\":\"適子庶子見於外寢，撫其首咳而名之，禮帥初，無辭。\",\"sentenceIds\":[\"li-ji_ch-12_p-69_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"適子庶子見於外寢，撫他的首咳而且名的，禮儀規程與道崇高德行與品性修養規範帥初，無辭。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 69 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「適子庶子見於外寢，撫其首咳而名之，禮帥初，無辭」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「適子庶子見於外寢，撫其首咳而名之，禮帥初，無辭。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-70\",\"chapterId\":\"li-ji_ch-12\",\"order\":70,\"canonicalText\":\"凡名子，不以日月，不以國，不以隱疾；大夫、士之子，不敢與世子同名。\",\"sentenceIds\":[\"li-ji_ch-12_p-70_s-1\",\"li-ji_ch-12_p-70_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡名子，不以日月，不以國，不以隱疾；卿大夫貴族官員、士人階層的子，不敢與世子同名。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 70 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡名子，不以日月，不以國，不以隱疾」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡名子，不以日月，不以國，不以隱疾；大夫、士之子，不……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-71\",\"chapterId\":\"li-ji_ch-12\",\"order\":71,\"canonicalText\":\"妾將生子，及月辰，夫使人日一問之。子生三月之末，漱浣夙齊，見於內寢，禮之如始入室；君已食，徹焉，使之特餕，遂入御。\",\"sentenceIds\":[\"li-ji_ch-12_p-71_s-1\",\"li-ji_ch-12_p-71_s-2\",\"li-ji_ch-12_p-71_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"妾將生子，及月辰，夫使人日一問的。子生三月的末，漱浣夙齊，見於內寢，禮儀規程與道崇高德行與品性修養規範的如始入室；君已食，徹焉，使的特餕，遂入御。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 71 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「妾將生子，及月辰，夫使人日一問之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「妾將生子，及月辰，夫使人日一問之。子生三月之末，漱浣……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-72\",\"chapterId\":\"li-ji_ch-12\",\"order\":72,\"canonicalText\":\"公庶子生，就側室。三月之末，其母沐浴朝服見於君，擯者以其子見，君所有賜，君名之。眾子，則使有司名之。\",\"sentenceIds\":[\"li-ji_ch-12_p-72_s-1\",\"li-ji_ch-12_p-72_s-2\",\"li-ji_ch-12_p-72_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"公庶子生，就側室。三月的末，他的母沐浴朝服見於君，擯的人或禮儀規程與道崇高德行與品性修養規範制規範以他的子見，君所有賜，君名的。眾子，則使有司名的。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 72 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「公庶子生，就側室」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「公庶子生，就側室。三月之末，其母沐浴朝服見於君，擯者……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-73\",\"chapterId\":\"li-ji_ch-12\",\"order\":73,\"canonicalText\":\"庶人無側室者，及月辰，夫出居羣室，其問之也，與子見父之禮，無以異也。\",\"sentenceIds\":[\"li-ji_ch-12_p-73_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"平民百姓無側室的人或禮儀規程與道崇高德行與品性修養規範制規範，及月辰，夫出居羣室，他的問的啊，與子見父的禮儀規程與道崇高德行與品性修養規範，無以異啊。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 73 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「庶人無側室者，及月辰，夫出居羣室，其問之也，與子見父之禮，無以異也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「庶人無側室者，及月辰，夫出居羣室，其問之也，與子見父……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-74\",\"chapterId\":\"li-ji_ch-12\",\"order\":74,\"canonicalText\":\"凡父在，孫見於祖，祖亦名之，禮如子見父，無辭。\",\"sentenceIds\":[\"li-ji_ch-12_p-74_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡父在，孫見於祖，祖亦名的，禮儀規程與道崇高德行與品性修養規範如子見父，無辭。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 74 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡父在，孫見於祖，祖亦名之，禮如子見父，無辭」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡父在，孫見於祖，祖亦名之，禮如子見父，無辭。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-75\",\"chapterId\":\"li-ji_ch-12\",\"order\":75,\"canonicalText\":\"食子者，三年而出，見於公宮則劬。大夫之子有食母，士之妻自養其子。\",\"sentenceIds\":[\"li-ji_ch-12_p-75_s-1\",\"li-ji_ch-12_p-75_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"食子的人或禮儀規程與道崇高德行與品性修養規範制規範，三年而且出，見於公宮則劬。卿大夫貴族官員的子有食母，士人階層的妻自養他的子。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 75 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「食子者，三年而出，見於公宮則劬」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「食子者，三年而出，見於公宮則劬。大夫之子有食母，士之……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-76\",\"chapterId\":\"li-ji_ch-12\",\"order\":76,\"canonicalText\":\"由命士以上及大夫之子，旬而見。冢子未食而見，必執其右手，適子庶子已食而見，必循其首。\",\"sentenceIds\":[\"li-ji_ch-12_p-76_s-1\",\"li-ji_ch-12_p-76_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"由命士人階層以上及卿大夫貴族官員的子，旬而且見。冢子未食而且見，必執他的右手，適子庶子已食而且見，必循他的首。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 76 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「由命士以上及大夫之子，旬而見」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「由命士以上及大夫之子，旬而見。冢子未食而見，必執其右……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-77\",\"chapterId\":\"li-ji_ch-12\",\"order\":77,\"canonicalText\":\"子能食食，教以右手。能言，男唯女俞。男鞶革，女鞶絲。\",\"sentenceIds\":[\"li-ji_ch-12_p-77_s-1\",\"li-ji_ch-12_p-77_s-2\",\"li-ji_ch-12_p-77_s-3\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"古代教養幼兒禮儀法度：幼兒到了能夠自己抓食飯菜之時，便應教導其用右手拿取進食；到了開始能夠牙牙學語之時，教導男童應諾回答用宏亮之『唯』聲，教導女童應答用溫順之『俞』聲；男童腰間佩戴象徵剛健勞作之皮製鞶帶，女童腰間佩戴象徵溫婉女紅之絲編絲帶。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 77 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子能食食，教以右手」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子能食食，教以右手。能言，男唯女俞。男鞶革，女鞶絲。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-78\",\"chapterId\":\"li-ji_ch-12\",\"order\":78,\"canonicalText\":\"六年教之數與方名。七年男女不同席，不共食。八年出入門戶及即席飲食，必後長者，始教之讓。九年教之數日。\",\"sentenceIds\":[\"li-ji_ch-12_p-78_s-1\",\"li-ji_ch-12_p-78_s-2\",\"li-ji_ch-12_p-78_s-3\",\"li-ji_ch-12_p-78_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"六年教的數與方名。七年男女不同席，不共食。八年出入門戶及即席飲食，必後長的人或禮儀規程與道崇高德行與品性修養規範制規範，始教的讓。九年教的數日。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 78 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「六年教之數與方名」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「六年教之數與方名。七年男女不同席，不共食。八年出入門……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-79\",\"chapterId\":\"li-ji_ch-12\",\"order\":79,\"canonicalText\":\"十年出就外傅，居宿於外，學書計，衣不帛襦褲，禮帥初，朝夕學幼儀，請肄簡諒。\",\"sentenceIds\":[\"li-ji_ch-12_p-79_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"男孩長到十歲之時，離開內宅走出深閨，正式拜從外學老師「外傅」求學，日常起居宿留於學舍之中；開始學習識字六書與九九乘除算數之法；平時穿著粗布衣袍，不可穿著昂貴華美的絲帛夾襖與絲綢套褲；所行禮節一切恪遵質樸初規；早晚用心學習童子待人接物的各類幼年威儀禮節；請求演練溫和恭順、明簡誠實的崇高品格。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 79 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「十年出就外傅，居宿於外，學書計，衣不帛襦褲，禮帥初，朝夕學幼儀，請肄簡諒」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「十年出就外傅，居宿於外，學書計，衣不帛襦褲，禮帥初，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-80\",\"chapterId\":\"li-ji_ch-12\",\"order\":80,\"canonicalText\":\"十有三年學樂，誦《詩》，舞《勺》，成童舞《象》，學射御。二十而冠，始學禮，可以衣裘帛，舞《大夏》，惇行孝弟，博學不教，內而不出。\",\"sentenceIds\":[\"li-ji_ch-12_p-80_s-1\",\"li-ji_ch-12_p-80_s-2\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"男孩長到十三歲之際，開始系統學習宮廷雅樂，誦讀背誦三千《詩經》篇章，演練學習幼年文舞《勺舞》；等到十五歲「成童」之年，開始學習威武宏大的武舞《象舞》，系統學習射箭與駕馭戰車的軍事武備技藝。年滿二十歲之時舉行隆重的成人冠禮，從此正式深入鑽研各類吉凶賓軍嘉大禮；此時方才可以正式身著暖裘皮袍與錦繡絲帛，演練夏禹開創之雄壯大舞《大夏》；在日用倫常中篤實踐行孝敬父母友愛兄弟的孝悌大節；廣泛博覽群書追求學問卻深自謙卑不自詡為師，涵養道德深藏若虛而不輕易浮誇外露。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 80 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「十有三年學樂，誦《詩》，舞《勺》，成童舞《象》，學射御」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「十有三年學樂，誦《詩》，舞《勺》，成童舞《象》，學射……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-81\",\"chapterId\":\"li-ji_ch-12\",\"order\":81,\"canonicalText\":\"三十而有室，始理男事，博學無方，孫友視志。四十始仕，方物出謀發慮，道合則服從，不可則去。五十命為大夫，服官政。七十致事。凡男拜，尚左手。\",\"sentenceIds\":[\"li-ji_ch-12_p-81_s-1\",\"li-ji_ch-12_p-81_s-2\",\"li-ji_ch-12_p-81_s-3\",\"li-ji_ch-12_p-81_s-4\",\"li-ji_ch-12_p-81_s-5\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"男子長到三十歲之時成家娶妻立室，開始全面掌理男子應當擔當的家國事業；博採眾長廣泛求學而無門戶局限之偏見，溫和遜讓結交各方賢友以審察砥礪彼此志向。四十歲之時正式出仕入朝為官，依照事物客觀倫理與治國法則為君王擘畫謀略運籌帷幄，若是政見相合道義相同則恪盡職守全力輔佐，若是道不相合信念違背則潔身自好退隱離去。五十歲之時榮獲天子諸侯冊命晉升為大夫之職，全面總攬負責一官之政務與典章治理。年屆七十歲之時自覺精力不濟，正式將官職政權交還國君告老致仕退休。凡是男子行作揖拜謝之禮，皆以左手覆在右手之上以示崇尚生機向陽之德。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 81 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「三十而有室，始理男事，博學無方，孫友視志」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「三十而有室，始理男事，博學無方，孫友視志。四十始仕，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-82\",\"chapterId\":\"li-ji_ch-12\",\"order\":82,\"canonicalText\":\"女子十年不出，姆教婉娩聽從，執麻枲，治絲繭，織紝組紃，學女事以共衣服，觀於祭祀，納酒漿、籩豆、菹醢，禮相助奠。\",\"sentenceIds\":[\"li-ji_ch-12_p-82_s-1\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"女孩子長到十歲之後便不出深閨遠遊，由資深女師女姆傳授溫柔順從、婉娩溫良、聽從長輩教誨的美好德行；親手操持大麻苧麻的紡績撚線，學習煮繭繅絲，熟練掌握紡織織錦、編織絲絛花帶與結紐組紃之術，全面精通各類女紅針線手藝以充分供給全家人的衣裳穿戴；在旁端肅觀摩家族祭祀的盛大典禮，協助端送盛酒的酒漿器皿，擺設盛盛乾鮮果品與乾肉菜餚的籩豆祭器，進獻調和的各色醃菜與肉醬，完全依照禮節規範輔助長輩陳設祭品以圓滿成就祭奠。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 82 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「女子十年不出，姆教婉娩聽從，執麻枲，治絲繭，織紝組紃，學女事以共衣服，觀於祭祀，納酒漿、籩豆、菹醢，禮相助奠」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「女子十年不出，姆教婉娩聽從，執麻枲，治絲繭，織紝組紃……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"li-ji_ch-12_p-83\",\"chapterId\":\"li-ji_ch-12\",\"order\":83,\"canonicalText\":\"十有五年而笄，二十而嫁；有故，二十三年而嫁。聘則為妻，奔則為妾。凡女拜尚右手。\",\"sentenceIds\":[\"li-ji_ch-12_p-83_s-1\",\"li-ji_ch-12_p-83_s-2\",\"li-ji_ch-12_p-83_s-3\",\"li-ji_ch-12_p-83_s-4\"],\"sourceRefs\":[{\"label\":\"《禮記》—中國哲學書電子化計劃\",\"edition\":\"阮元校刻《十三經註疏・禮記正義》\",\"location\":\"https://ctext.org/liji/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《禮記》—維基文庫\",\"edition\":\"鄭玄注・孔穎達疏《禮記正義》\",\"location\":\"https://zh.wikisource.org/zh-hant/禮記\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"十有五年而且笄，二十而且嫁；有所以，二十三年而且嫁。聘則為妻，奔則為妾。凡女拜尚右手。\",\"analysis\":\"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈內則〉（第 83 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「十有五年而笄，二十而嫁」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「十有五年而笄，二十而嫁；有故，二十三年而嫁。聘則為妻……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"li-ji_ch-12_p-1_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-1\",\"order\":1,\"canonicalText\":\"后王命冢宰，降德於眾兆民。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-2_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-2\",\"order\":1,\"canonicalText\":\"子事父母，雞初鳴，鹹盥漱，櫛縰笄總，拂髦冠緌纓，端韠紳，搢笏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-2_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-2\",\"order\":2,\"canonicalText\":\"左右佩用，左佩紛帨、刀、礪、小觿、金燧，右佩玦、捍、管、遰、大觿、木燧，偪，屨著綦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-3_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-3\",\"order\":1,\"canonicalText\":\"婦事舅姑，如事父母。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-3_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-3\",\"order\":2,\"canonicalText\":\"雞初鳴，鹹盥漱，櫛縰，笄總，衣紳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-3_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-3\",\"order\":3,\"canonicalText\":\"左佩紛帨、刀、礪、小觿、金燧，右佩箴、管、線、纊，施縏帙，大觿、木燧、衿纓，綦屨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-4_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-4\",\"order\":1,\"canonicalText\":\"以適父母舅姑之所，及所，下氣怡聲，問衣燠寒，疾痛苛癢，而敬抑搔之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-4_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-4\",\"order\":2,\"canonicalText\":\"出入，則或先或後，而敬扶持之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-4_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-4\",\"order\":3,\"canonicalText\":\"進盥，少者奉盤，長者奉水，請沃盥，盥卒授巾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-4_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-4\",\"order\":4,\"canonicalText\":\"問所欲而敬進之，柔色以溫之，饘酏、酒醴、芼羹、菽麥、蕡稻、黍粱、秫唯所欲，棗、栗、飴、蜜以甘之，堇、荁、枌、榆免槁薧滫以滑之，脂膏以膏之，父母舅姑必嘗之而後退。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-5_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-5\",\"order\":1,\"canonicalText\":\"男女未冠笄者，雞初鳴，鹹盥漱，櫛縰，拂髦總角，衿纓，皆佩容臭，昧爽而朝，問何食飲矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-5_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-5\",\"order\":2,\"canonicalText\":\"若已食則退，若未食則佐長者視具。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-6_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-6\",\"order\":1,\"canonicalText\":\"凡內外，雞初鳴，鹹盥漱，衣服，斂枕簟，灑掃室堂及庭，布席，各從其事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-7_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-7\",\"order\":1,\"canonicalText\":\"孺子蚤寢晏起，唯所欲，食無時。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-8_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-8\",\"order\":1,\"canonicalText\":\"由命士以上，父子皆異宮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-8_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-8\",\"order\":2,\"canonicalText\":\"昧爽而朝，慈以旨甘，日出而退，各從其事，日入而夕，慈以旨甘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-9_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-9\",\"order\":1,\"canonicalText\":\"父母舅姑將坐，奉席請何鄉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-9_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-9\",\"order\":2,\"canonicalText\":\"將衽，長者奉席請何趾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-9_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-9\",\"order\":3,\"canonicalText\":\"少者執牀與坐，御者舉幾，斂席與簟，縣衾篋枕，斂簟而襡之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-10_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-10\",\"order\":1,\"canonicalText\":\"父母舅姑之衣衾簟席枕幾不傳，杖屨只敬之，勿敢近。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-10_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-10\",\"order\":2,\"canonicalText\":\"敦牟卮匜，非餕莫敢用；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-10_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-10\",\"order\":3,\"canonicalText\":\"與恆食飲，非餕，莫之敢飲食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-11_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-11\",\"order\":1,\"canonicalText\":\"父母在，朝夕恆食，子婦佐餕，既食恆餕，父沒母存，冢子御食，羣子婦佐餕如初，旨甘柔滑，孺子餕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-12_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-12\",\"order\":1,\"canonicalText\":\"在父母舅姑之所，有命之，應唯敬對。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-12_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-12\",\"order\":2,\"canonicalText\":\"進退周旋慎齊，升降出入揖遊，不敢噦噫、嚏咳、欠伸、跛倚、睇視，不敢唾洟；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-12_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-12\",\"order\":3,\"canonicalText\":\"寒不敢襲，癢不敢搔；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-12_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-12\",\"order\":4,\"canonicalText\":\"不有敬事，不敢袒裼，不涉不撅，褻衣衾不見裏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-13_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-13\",\"order\":1,\"canonicalText\":\"父母唾洟不見，冠帶垢，和灰請漱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-13_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-13\",\"order\":2,\"canonicalText\":\"衣裳垢，和灰請浣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-13_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-13\",\"order\":3,\"canonicalText\":\"衣裳綻裂，紉箴請補綴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-13_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-13\",\"order\":4,\"canonicalText\":\"五日，則燂湯請浴，三日具沐，其間面垢，燂潘請靧；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-13_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-13\",\"order\":5,\"canonicalText\":\"足垢，燂湯請洗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-13_s-6\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-13\",\"order\":6,\"canonicalText\":\"少事長，賤事貴，共帥時。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-14_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-14\",\"order\":1,\"canonicalText\":\"男不言內，女不言外。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-14_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-14\",\"order\":2,\"canonicalText\":\"非祭非喪，不相授器。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-14_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-14\",\"order\":3,\"canonicalText\":\"其相授，則女受以篚，其無篚則皆坐奠之而後取之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-14_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-14\",\"order\":4,\"canonicalText\":\"外內不共井，不共湢浴，不通寢席，不通乞假，男女不通衣裳，內言不出，外言不入。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-15_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-15\",\"order\":1,\"canonicalText\":\"男子入內，不嘯不指，夜行以燭，無燭則止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-15_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-15\",\"order\":2,\"canonicalText\":\"女子出門，必擁蔽其面，夜行以燭，無燭則止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-15_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-15\",\"order\":3,\"canonicalText\":\"道路：男子由右，女子由左。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-16_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-16\",\"order\":1,\"canonicalText\":\"子婦孝者、敬者，父母舅姑之命，勿逆勿怠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-16_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-16\",\"order\":2,\"canonicalText\":\"若飲食之，雖不耆，必嘗而待；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-16_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-16\",\"order\":3,\"canonicalText\":\"加之衣服，雖不欲，必服而待；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-16_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-16\",\"order\":4,\"canonicalText\":\"加之事，人待之，己雖弗欲，姑與之，而姑使之，而後復之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-17_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-17\",\"order\":1,\"canonicalText\":\"子婦有勤勞之事，雖甚愛之，姑縱之，而寧數休之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-17_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-17\",\"order\":2,\"canonicalText\":\"子婦未孝未敬，勿庸疾怨，姑教之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-17_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-17\",\"order\":3,\"canonicalText\":\"若不可教，而後怒之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-17_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-17\",\"order\":4,\"canonicalText\":\"不可怒，子放婦出，而不表禮焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-18_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-18\",\"order\":1,\"canonicalText\":\"父母有過，下氣怡色，柔聲以諫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-18_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-18\",\"order\":2,\"canonicalText\":\"諫若不入，起敬起孝，說則復諫；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-18_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-18\",\"order\":3,\"canonicalText\":\"不說，與其得罪於鄉黨州閭，寧孰諫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-18_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-18\",\"order\":4,\"canonicalText\":\"父母怒、不說，而撻之流血，不敢疾怨，起敬起孝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-19_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-19\",\"order\":1,\"canonicalText\":\"父母有婢子若庶子、庶孫，甚愛之，雖父母沒，沒身敬之不衰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-20_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-20\",\"order\":1,\"canonicalText\":\"子有二妾，父母愛一人焉，子愛一人焉，由衣服飲食，由執事，毋敢視父母所愛，雖父母沒不衰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-20_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-20\",\"order\":2,\"canonicalText\":\"子甚宜其妻，父母不說，出；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-20_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-20\",\"order\":3,\"canonicalText\":\"子不宜其妻，父母曰：「是善事我。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-20_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-20\",\"order\":4,\"canonicalText\":\"」子行夫婦之禮焉，沒身不衰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-21_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-21\",\"order\":1,\"canonicalText\":\"父母雖沒，將為善，思貽父母令名，必果；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-21_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-21\",\"order\":2,\"canonicalText\":\"將為不善，思貽父母羞辱，必不果。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-22_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-22\",\"order\":1,\"canonicalText\":\"舅沒則姑老，冢婦所祭祀、賓客，每事必請於姑，介婦請於冢婦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-22_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-22\",\"order\":2,\"canonicalText\":\"舅姑使冢婦，毋怠，不友無禮於介婦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-22_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-22\",\"order\":3,\"canonicalText\":\"舅姑若使介婦，毋敢敵耦於冢婦，不敢並行，不敢並命，不敢並坐。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-23_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-23\",\"order\":1,\"canonicalText\":\"凡婦，不命適私室，不敢退。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-23_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-23\",\"order\":2,\"canonicalText\":\"婦將有事，大小必請於舅姑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-23_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-23\",\"order\":3,\"canonicalText\":\"子婦無私貨，無私畜，無私器，不敢私假，不敢私與。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-23_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-23\",\"order\":4,\"canonicalText\":\"婦或賜之飲食、衣服、布帛、佩帨、茝蘭，則受而獻諸舅姑，舅姑受之則喜，如新受賜，若反賜之則辭，不得命，如更受賜，藏以待乏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-23_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-23\",\"order\":5,\"canonicalText\":\"婦若有私親兄弟將與之，則必復請其故，賜而後與之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-24_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-24\",\"order\":1,\"canonicalText\":\"適子庶子只事宗子宗婦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-24_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-24\",\"order\":2,\"canonicalText\":\"雖貴富，不敢以貴富入宗子之家，雖眾車徒舍於外，以寡約入。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-25_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-25\",\"order\":1,\"canonicalText\":\"子弟猶歸器衣服裘衾車馬，則必獻其上，而後敢服用其次也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-25_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-25\",\"order\":2,\"canonicalText\":\"若非所獻，則不敢以入於宗子之門，不敢以貴富加於父兄宗族。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-25_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-25\",\"order\":3,\"canonicalText\":\"若富，則具二牲，獻其賢者於宗子，夫婦皆齊而宗敬焉，終事而後敢私祭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-26_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-26\",\"order\":1,\"canonicalText\":\"飯：黍，稷，稻，粱，白黍，黃粱，稰，穛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-27_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-27\",\"order\":1,\"canonicalText\":\"膳：膷，臐，膮，醢，牛炙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-27_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-27\",\"order\":2,\"canonicalText\":\"醢，牛胾，醢，牛膾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-27_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-27\",\"order\":3,\"canonicalText\":\"羊炙，羊胾，醢，豕炙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-27_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-27\",\"order\":4,\"canonicalText\":\"醢，豕胾，芥醬，魚膾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-27_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-27\",\"order\":5,\"canonicalText\":\"雉，兔，鶉，鷃。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-28_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-28\",\"order\":1,\"canonicalText\":\"飲：重醴，稻醴清糟，黍醴清糟，粱醴清糟，或以酏為醴，黍酏，漿，水，醷，濫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-29_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-29\",\"order\":1,\"canonicalText\":\"酒：清、白。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-30_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-30\",\"order\":1,\"canonicalText\":\"羞：糗，餌，粉，酏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-31_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-31\",\"order\":1,\"canonicalText\":\"食：蝸醢而菰食，雉羹；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-31_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-31\",\"order\":2,\"canonicalText\":\"麥食，脯羹，雞羹；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-31_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-31\",\"order\":3,\"canonicalText\":\"析稌，犬羹，兔羹；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-31_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-31\",\"order\":4,\"canonicalText\":\"和糝不蓼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-32_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-32\",\"order\":1,\"canonicalText\":\"濡豚，包苦實蓼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-32_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-32\",\"order\":2,\"canonicalText\":\"濡雞，醢醬實蓼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-32_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-32\",\"order\":3,\"canonicalText\":\"濡魚，卵醬實蓼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-32_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-32\",\"order\":4,\"canonicalText\":\"濡鱉，醢醬實蓼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-33_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-33\",\"order\":1,\"canonicalText\":\"腶修，蚳醢，脯羹，兔醢，糜膚，魚醢，魚膾，芥醬，麋腥，醢，醬，桃諸，梅諸，卵鹽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-34_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-34\",\"order\":1,\"canonicalText\":\"凡食齊視春時，羹齊視夏時，醬齊視秋時，飲齊視冬時。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-35_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-35\",\"order\":1,\"canonicalText\":\"凡和，春多酸，夏多苦，秋多辛，冬多鹹，調以滑甘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-36_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-36\",\"order\":1,\"canonicalText\":\"牛宜稌，羊宜黍，豕宜稷，犬宜粱，雁宜麥，魚宜菰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-37_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-37\",\"order\":1,\"canonicalText\":\"春宜羔豚膳膏薌，夏宜腒鱐膳膏臊，秋宜犢麑膳膏腥，冬宜鮮羽膳膏羶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-38_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-38\",\"order\":1,\"canonicalText\":\"牛修，鹿脯，田豕脯，糜脯，麇脯，麋、鹿、田豕、麇，皆有軒，雉兔皆有芼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-38_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-38\",\"order\":2,\"canonicalText\":\"爵，鷃，蜩，範，芝栭，菱，椇，棗，栗，榛，柿，瓜，桃，李，梅，杏，楂，梨，姜，桂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-39_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-39\",\"order\":1,\"canonicalText\":\"大夫燕食，有膾無脯，有脯無膾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-39_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-39\",\"order\":2,\"canonicalText\":\"士不貳羹胾，庶人耆老不徒食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-40_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-40\",\"order\":1,\"canonicalText\":\"膾：春用蔥，秋用芥、豚；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-40_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-40\",\"order\":2,\"canonicalText\":\"春用韭，秋用蓼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-40_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-40\",\"order\":3,\"canonicalText\":\"脂用蔥，膏用薤，三牲用藙，和用醯，獸用梅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-40_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-40\",\"order\":4,\"canonicalText\":\"鶉羹、雞羹、鴽，釀之蓼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-40_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-40\",\"order\":5,\"canonicalText\":\"魴鱮烝，雛燒，雉，薌無蓼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-41_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-41\",\"order\":1,\"canonicalText\":\"不食雛鱉，狼去腸，狗去腎，貍去正脊，兔去尻，狐去首，豚去腦，魚去乙，鱉去醜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-42_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-42\",\"order\":1,\"canonicalText\":\"肉曰脫之，魚曰作之，棗曰新之，栗曰撰之，桃曰膽之，柤梨曰攢之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-43_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-43\",\"order\":1,\"canonicalText\":\"牛夜鳴則庮，羊泠毛而毳、羶，狗赤股而躁、臊，鳥麃色而沙鳴、鬱，豕望視而交睫、腥，馬黑脊而般臂、漏，雛尾不盈握弗食，舒雁翠，鵠鴞胖，舒鳧翠，雞肝，雁腎，鴇奧，鹿胃。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-44_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-44\",\"order\":1,\"canonicalText\":\"肉腥細者為膾，大者為軒；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-44_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-44\",\"order\":2,\"canonicalText\":\"或曰麋鹿魚為菹，麇為闢雞，野豕為軒，兔為宛脾，切蔥若薤，實諸醯以柔之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-45_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-45\",\"order\":1,\"canonicalText\":\"羹食，自諸侯以下至於庶人無等。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-46_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-46\",\"order\":1,\"canonicalText\":\"大夫無秩膳，大夫七十而有閣，天子之閣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-46_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-46\",\"order\":2,\"canonicalText\":\"左達五，右達五，公侯伯於房中五，大夫於閣三，士於坫一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":1,\"canonicalText\":\"凡養老：有虞氏以燕禮，夏后氏以饗禮，殷人以食禮，周人修而兼用之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":2,\"canonicalText\":\"凡五十養於鄉，六十養於國，七十養於學，達於諸侯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":3,\"canonicalText\":\"八十拜君命，一坐再至，瞽亦如之，九十者使人受。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":4,\"canonicalText\":\"五十異粻，六十宿肉，七十二膳，八十常珍，九十飲食不違寢，膳飲從於遊可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":5,\"canonicalText\":\"六十歲制，七十時制，八十月制，九十日修，唯絞紟衾冒，死而後制。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-6\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":6,\"canonicalText\":\"五十始衰，六十非肉不飽，七十非帛不暖，八十非人不暖，九十雖得人不暖矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-7\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":7,\"canonicalText\":\"五十杖於家，六十杖於鄉，七十杖於國，八十杖於朝，九十者天子欲有問焉，則就其室以珍從。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-8\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":8,\"canonicalText\":\"七十不俟朝，八十月告存，九十日有秩。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-9\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":9,\"canonicalText\":\"五十不從力政，六十不與服戎，七十不與賓客之事，八十齊喪之事弗及也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-10\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":10,\"canonicalText\":\"五十而爵，六十不親學，七十致政；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-47_s-11\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-47\",\"order\":11,\"canonicalText\":\"凡自七十以上，唯衰麻為喪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":1,\"canonicalText\":\"凡三王養老皆引年，八十者一子不從政，九十者其家不從政；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":2,\"canonicalText\":\"瞽亦如之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":3,\"canonicalText\":\"凡父母在，子雖老不坐。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":4,\"canonicalText\":\"有虞氏養國老於上庠，養庶老於下庠；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":5,\"canonicalText\":\"夏后氏養國老於東序，養庶老於西序；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-6\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":6,\"canonicalText\":\"殷人養國老於右學，養庶老於左學；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-7\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":7,\"canonicalText\":\"周人養國老於東膠，養庶老於虞庠，虞庠在國之西郊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-8\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":8,\"canonicalText\":\"有虞氏皇而祭，深衣而養老；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-9\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":9,\"canonicalText\":\"夏后氏收而祭，燕衣而養老；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-10\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":10,\"canonicalText\":\"殷人冔而祭，縞衣而養老；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-48_s-11\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-48\",\"order\":11,\"canonicalText\":\"周人冕而祭，玄衣而養老。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-49_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-49\",\"order\":1,\"canonicalText\":\"曾子曰：「孝子之養老也，樂其心不違其志，樂其耳目，安其寢處，以其飲食忠養之孝子之身終，終身也者，非終父母之身，終其身也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-49_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-49\",\"order\":2,\"canonicalText\":\"是故父母之所愛亦愛之，父母之所敬亦敬之，至於犬馬盡然，而況於人乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-49_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-49\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-50_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-50\",\"order\":1,\"canonicalText\":\"凡養老，五帝憲，三王有乞言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-50_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-50\",\"order\":2,\"canonicalText\":\"五帝憲，養氣體而不乞言，有善則記之為惇史。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-50_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-50\",\"order\":3,\"canonicalText\":\"三王亦憲，既養老而後乞言，亦微其禮，皆有惇史。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-51_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-51\",\"order\":1,\"canonicalText\":\"淳熬：煎醢，加於陸稻上，沃之以膏曰淳熬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-51_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-51\",\"order\":2,\"canonicalText\":\"淳毋煎醢，加於黍食上，沃之以膏曰淳毋。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-52_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-52\",\"order\":1,\"canonicalText\":\"炮：取豚若將，刲之刳之，實棗於其腹中，編萑以苴之，塗之以謹塗，炮之，塗皆乾，擘之，濯手以摩之，去其皽，為稻粉糔溲之以為酏，以付豚煎諸膏，膏必滅之，鉅鑊湯以小鼎薌脯於其中，使其湯毋滅鼎，三日三夜毋絕火，而後調之以醯醢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-53_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-53\",\"order\":1,\"canonicalText\":\"搗珍：取牛羊麋鹿麇之肉必脄，每物與牛若一捶，反側之，去其餌，熟出之，去其餌，柔其肉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-54_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-54\",\"order\":1,\"canonicalText\":\"漬：取牛肉必新殺者，薄切之，必絕其理；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-54_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-54\",\"order\":2,\"canonicalText\":\"湛諸美酒，期朝而食之以醢若醯醷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-55_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-55\",\"order\":1,\"canonicalText\":\"為熬：捶之，去其皽，編萑布牛肉焉，屑桂與姜以灑諸上而鹽之，乾而食之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-55_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-55\",\"order\":2,\"canonicalText\":\"施羊亦如之，施麋、施鹿、施麇皆如牛羊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-55_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-55\",\"order\":3,\"canonicalText\":\"欲濡肉則釋而煎之以醢，欲乾肉則捶而食之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-56_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-56\",\"order\":1,\"canonicalText\":\"糝：取牛羊豕之肉，三如一小切之，與稻米；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-56_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-56\",\"order\":2,\"canonicalText\":\"稻米二肉一，合以為餌煎之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-57_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-57\",\"order\":1,\"canonicalText\":\"肝菺：取狽肝一，幪之，以其菺濡炙之，舉焦，其菺不蓼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-57_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-57\",\"order\":2,\"canonicalText\":\"取稻米舉糔溲之，小切狼臅膏，以與稻米為酏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-58_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-58\",\"order\":1,\"canonicalText\":\"禮，始於謹夫婦，為宮室，辨外內。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-58_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-58\",\"order\":2,\"canonicalText\":\"男子居外，女子居內，深宮固門，閽寺守之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-58_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-58\",\"order\":3,\"canonicalText\":\"男不入，女不出。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-59_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-59\",\"order\":1,\"canonicalText\":\"男女不同椸枷，不敢懸於夫之楎椸，不敢藏於夫之篋笥，不敢共湢浴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-59_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-59\",\"order\":2,\"canonicalText\":\"夫不在，斂枕篋簟席、襡器而藏之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-59_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-59\",\"order\":3,\"canonicalText\":\"少事長，賤事貴，鹹如之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-60_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-60\",\"order\":1,\"canonicalText\":\"夫婦之禮，唯及七十，同藏無間。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-60_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-60\",\"order\":2,\"canonicalText\":\"故妾雖老，年未滿五十，必與五日之御。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-60_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-60\",\"order\":3,\"canonicalText\":\"將御者，齊，漱浣，慎衣服，櫛縰笄，總角，拂髦，衿纓綦屨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-60_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-60\",\"order\":4,\"canonicalText\":\"雖婢妾，衣服飲食必後長者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-60_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-60\",\"order\":5,\"canonicalText\":\"妻不在，妾御莫敢當夕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-61_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-61\",\"order\":1,\"canonicalText\":\"妻將生子，及月辰，居側室，夫使人日再問之，作而自問之，妻不敢見，使姆衣服而對，至於子生，夫復使人日再問之，夫齊則不入側室之門。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-61_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-61\",\"order\":2,\"canonicalText\":\"子生，男子設弧於門左，女子設帨於門右。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-61_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-61\",\"order\":3,\"canonicalText\":\"三日，始負子，男射女否。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-62_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-62\",\"order\":1,\"canonicalText\":\"國君世子生，告於君，接以大牢，宰掌具。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-62_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-62\",\"order\":2,\"canonicalText\":\"三日，卜士負之，吉者宿齊朝服寢門外，詩負之，射人以桑弧蓬矢六。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-62_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-62\",\"order\":3,\"canonicalText\":\"射天地四方，保受乃負之，宰醴負子，賜之束帛，卜士之妻、大夫之妾，使食子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-63_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-63\",\"order\":1,\"canonicalText\":\"凡接子，擇日，冢子則大牢，庶人特豚，士特豕，大夫少牢，國君世子大牢，其非冢子，則皆降一等。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-64_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-64\",\"order\":1,\"canonicalText\":\"異為孺子室於宮中，擇於諸母與可者，必求其寬裕慈惠、溫良恭敬、慎而寡言者，使為子師，其次為慈母，其次為保母，皆居子室，他人無事不往。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-65_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-65\",\"order\":1,\"canonicalText\":\"三月之末，擇日剪發為鬌，男角女羈，否則男左女右。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-65_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-65\",\"order\":2,\"canonicalText\":\"是日也，妻以子見於父，貴人則為衣服，由命士以下，皆漱浣，男女夙興，沐浴衣服，具視朔食，夫入門，升自阼階。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-65_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-65\",\"order\":3,\"canonicalText\":\"立於阼西鄉，妻抱子出自房，當楣立東面。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-66_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-66\",\"order\":1,\"canonicalText\":\"姆先，相曰：「母某敢用時日只見孺子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-66_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-66\",\"order\":2,\"canonicalText\":\"」夫對曰：「欽有帥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-66_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-66\",\"order\":3,\"canonicalText\":\"」父執子之右手，咳而名之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-66_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-66\",\"order\":4,\"canonicalText\":\"妻對曰：「記有成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-66_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-66\",\"order\":5,\"canonicalText\":\"」遂左還，授師，子師辯告諸婦諸母名，妻遂適寢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-67_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-67\",\"order\":1,\"canonicalText\":\"夫告宰名，宰辯告諸男名，書曰：「某年某月某日某生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-67_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-67\",\"order\":2,\"canonicalText\":\"」而藏之，宰告閭史，閭史書為二，其一藏諸閭府，其一獻諸州史；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-67_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-67\",\"order\":3,\"canonicalText\":\"州史獻諸州伯，州伯命藏諸州府。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-67_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-67\",\"order\":4,\"canonicalText\":\"夫入食如養禮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-68_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-68\",\"order\":1,\"canonicalText\":\"世子生，則君沐浴朝服，夫人亦如之，皆立於阼階西鄉，世婦抱子升自西階，君名之，乃降。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-69_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-69\",\"order\":1,\"canonicalText\":\"適子庶子見於外寢，撫其首咳而名之，禮帥初，無辭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-70_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-70\",\"order\":1,\"canonicalText\":\"凡名子，不以日月，不以國，不以隱疾；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-70_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-70\",\"order\":2,\"canonicalText\":\"大夫、士之子，不敢與世子同名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-71_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-71\",\"order\":1,\"canonicalText\":\"妾將生子，及月辰，夫使人日一問之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-71_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-71\",\"order\":2,\"canonicalText\":\"子生三月之末，漱浣夙齊，見於內寢，禮之如始入室；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-71_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-71\",\"order\":3,\"canonicalText\":\"君已食，徹焉，使之特餕，遂入御。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-72_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-72\",\"order\":1,\"canonicalText\":\"公庶子生，就側室。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-72_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-72\",\"order\":2,\"canonicalText\":\"三月之末，其母沐浴朝服見於君，擯者以其子見，君所有賜，君名之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-72_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-72\",\"order\":3,\"canonicalText\":\"眾子，則使有司名之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-73_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-73\",\"order\":1,\"canonicalText\":\"庶人無側室者，及月辰，夫出居羣室，其問之也，與子見父之禮，無以異也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-74_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-74\",\"order\":1,\"canonicalText\":\"凡父在，孫見於祖，祖亦名之，禮如子見父，無辭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-75_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-75\",\"order\":1,\"canonicalText\":\"食子者，三年而出，見於公宮則劬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-75_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-75\",\"order\":2,\"canonicalText\":\"大夫之子有食母，士之妻自養其子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-76_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-76\",\"order\":1,\"canonicalText\":\"由命士以上及大夫之子，旬而見。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-76_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-76\",\"order\":2,\"canonicalText\":\"冢子未食而見，必執其右手，適子庶子已食而見，必循其首。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-77_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-77\",\"order\":1,\"canonicalText\":\"子能食食，教以右手。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-77_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-77\",\"order\":2,\"canonicalText\":\"能言，男唯女俞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-77_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-77\",\"order\":3,\"canonicalText\":\"男鞶革，女鞶絲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-78_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-78\",\"order\":1,\"canonicalText\":\"六年教之數與方名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-78_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-78\",\"order\":2,\"canonicalText\":\"七年男女不同席，不共食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-78_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-78\",\"order\":3,\"canonicalText\":\"八年出入門戶及即席飲食，必後長者，始教之讓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-78_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-78\",\"order\":4,\"canonicalText\":\"九年教之數日。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-79_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-79\",\"order\":1,\"canonicalText\":\"十年出就外傅，居宿於外，學書計，衣不帛襦褲，禮帥初，朝夕學幼儀，請肄簡諒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-80_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-80\",\"order\":1,\"canonicalText\":\"十有三年學樂，誦《詩》，舞《勺》，成童舞《象》，學射御。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-80_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-80\",\"order\":2,\"canonicalText\":\"二十而冠，始學禮，可以衣裘帛，舞《大夏》，惇行孝弟，博學不教，內而不出。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-81_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-81\",\"order\":1,\"canonicalText\":\"三十而有室，始理男事，博學無方，孫友視志。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-81_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-81\",\"order\":2,\"canonicalText\":\"四十始仕，方物出謀發慮，道合則服從，不可則去。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-81_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-81\",\"order\":3,\"canonicalText\":\"五十命為大夫，服官政。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-81_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-81\",\"order\":4,\"canonicalText\":\"七十致事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-81_s-5\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-81\",\"order\":5,\"canonicalText\":\"凡男拜，尚左手。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-82_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-82\",\"order\":1,\"canonicalText\":\"女子十年不出，姆教婉娩聽從，執麻枲，治絲繭，織紝組紃，學女事以共衣服，觀於祭祀，納酒漿、籩豆、菹醢，禮相助奠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-83_s-1\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-83\",\"order\":1,\"canonicalText\":\"十有五年而笄，二十而嫁；\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-83_s-2\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-83\",\"order\":2,\"canonicalText\":\"有故，二十三年而嫁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-83_s-3\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-83\",\"order\":3,\"canonicalText\":\"聘則為妻，奔則為妾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"li-ji_ch-12_p-83_s-4\",\"workId\":\"li-ji\",\"chapterId\":\"li-ji_ch-12\",\"passageId\":\"li-ji_ch-12_p-83\",\"order\":4,\"canonicalText\":\"凡女拜尚右手。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
